{"command": "cd /tmp/w && python3 - <<'EOF'
import re,collections,json
def ids(f): return set(re.findall(r'<checker id="([^"]*)"',open(f).read()))
lines=open('/tmp/cr.txt').read().split('\n')
req={}
for l in lines:
    m=re.match(r'^(Yes|No)\s+(\S+)(?:\s+require:(.*))?$',l)
    if m: req[m.group(2)]=(m.group(1)=='Yes',[t for t in (m.group(3) or '').split(',') if t])
cfgs=['all','allinconclusive','allinconclusivesafety','allinconclusiveplatformwin32A','allinconclusivestdc++11','allinconclusivestdc++03']
sets={}
for lang in ['c','cpp']:
    for cfg in cfgs:
        sets[(lang,cfg)]=ids(f'/tmp/S_{lang}_{cfg}.xml')
# derive lang condition using the most permissive config
full='allinconclusivestdc++11'
langcond={}
for n in req:
    ic = n in sets[('c',full)]; ip = n in sets[('cpp',full)]
    langcond[n] = 'both' if (ic and ip) else ('cpp' if ip else ('c' if ic else 'none'))
json.dump({n:{'req':v[1],'lang':langcond[n]} for n,v in req.items()}, open('/tmp/checkers.json','w'))
print("lang none count:", sum(1 for v in langcond.values() if v=='none'))
print([n for n,v in langcond.items() if v=='none'])
# c-only
print("c-only:",[n for n,v in langcond.items() if v=='c'])
# verify: for each config, predicted active = all req satisfied and lang ok
def sat(tok, severities, inc, safety, win, std, lang):
    if tok in ('style','warning','performance','portability','information','unusedFunction','missingInclude'): return tok in severities
    if tok=='inconclusive': return inc
    if tok=='safeChecks': return safety
    if tok=='windows-platform': return win
    if tok=='c++': return lang=='cpp'
    if tok=='c': return lang=='c'
    if tok=='c++03': return lang=='cpp' and std=='c++03'
    if tok=='c++11': return lang=='cpp' and std in ('c++11','c++14','c++17','c++20')
    return True
EOF"}

