{"command": "cd /tmp/w && python3 - <<'EOF'
import re,json
def ids(f): return set(re.findall(r'<checker id="([^"]*)"',open(f).read()))
d=json.load(open('/tmp/checkers.json'))
ss=json.load(open('/tmp/sevsets.json'))
sevs=['style','warning','performance','portability','information','unusedFunction','missingInclude']
tbl={}
mismatch=[]
for n,v in d.items():
    lang=v['lang']
    # severity sets
    sevC=set(); sevCpp=set()
    for s in sevs:
        if n in ss[f"{s}|c"]: sevC.add(s)
        if n in ss[f"{s}|cpp"]: sevCpp.add(s)
    if lang=='both' and sevC!=sevCpp: mismatch.append((n,sorted(sevC),sorted(sevCpp)))
    # non-sev reqs
    ns=[t for t in v['req'] if t not in sevs and t not in ('c','c++','safeChecks')]
    tbl[n]={'lang':lang,'sev':sorted(sevCpp if lang=='cpp' else sevC),'ns':ns}
print("sev mismatches (both-lang):",mismatch)
json.dump(tbl,open('/tmp/tbl.json','w'),indent=0)
# summary of non-sev tokens
import collections
print(collections.Counter(t for n,v in tbl.items() for t in v['ns']))
print("checkers with empty sev:",[n for n,v in tbl.items() if not v['sev']])
EOF"}

