{"command": "cd /tmp/w && python3 - <<'EOF'
import re,json
d=json.load(open('/tmp/checkers.json')); ss=json.load(open('/tmp/sevsets.json'))
sevs=['style','warning','performance','portability','information','unusedFunction','missingInclude']
tbl={}
for n,v in d.items():
    lang=v['lang']
    sev=set(s for s in sevs if n in ss[f"{s}|cpp"]) if lang!='c' else set(s for s in sevs if n in ss[f"{s}|c"])
    if lang=='both':
        sevC=set(s for s in sevs if n in ss[f"{s}|c"])
        if sevC!=sev: print("MISMATCH sev",n)
    req=v['req']
    if n=='CheckMemoryLeakNoVar::checkForUnsafeArgAlloc': req=['inconclusive']; lang='cpp'; sev={'warning'}
    if n=='CheckIO::checkCoutCerrMisusage': req=[]; lang='cpp'
    if n=='CheckClass::checkConst': req=['style','inconclusive']
    ns=[t for t in req if t not in sevs]
    sev = sev | set(t for t in req if t in sevs)
    tbl[n]={'lang':lang,'sev':sorted(sev),'ns':sorted(ns)}
tbl['CheckStl::size']={'lang':'cpp','sev':['performance'],'ns':['c++03exact']}
tbl['CheckClass::checkMissingOverride']={'lang':'cpp','sev':['style'],'ns':['notc++03']}
tbl['CheckFunctions::returnLocalStdMove']={'lang':'cpp','sev':['performance'],'ns':['notc++03']}
tbl['CheckOther::checkAccessOfMovedVariable']={'lang':'cpp','sev':['warning'],'ns':['notc++03']}
json.dump(tbl,open('/tmp/tbl.json','w'),indent=0)
for n in ['CheckBufferOverrun::stringNotZeroTerminated','CheckBool::checkBitwiseOnBoolean','CheckClass::checkConst','CheckOther::checkRedundantCopy','CheckClass::checkUnsafeClassRefMember','CheckOther::checkInterlockedDecrement']:
    print(n, tbl[n])
EOF"}

