{"command": "cd /tmp/w && python3 - <<'EOF'
import re,json,subprocess
def ids(f): return set(re.findall(r'<checker id="([^"]*)"',open(f).read()))
d=json.load(open('/tmp/checkers.json')); ss=json.load(open('/tmp/sevsets.json'))
sevs=['style','warning','performance','portability','information','unusedFunction','missingInclude']
# measure incSet
inc={}
for lang,f in (('c','c.c'),('cpp','e.cpp')):
    a=set(re.findall(r'<checker id="([^"]*)"',subprocess.run(["/workspace/executable","--enable=all",f"--output-format=xmlv3",f],capture_output=True,text=True).stderr))
    b=set(re.findall(r'<checker id="([^"]*)"',subprocess.run(["/workspace/executable","--enable=all","--inconclusive",f"--output-format=xmlv3",f],capture_output=True,text=True).stderr))
    inc[lang]=sorted(b-a)
print("incSet c:",inc['c']); print("incSet cpp:",inc['cpp'])
json.dump(inc,open('/tmp/inc.json','w'))
# per-checker lang + special
lang={}
for n,v in d.items():
    # derive from all-sets
    lang[n]=v['lang']
# fix lang using win32A config too
def fixlang():
    sets={}
    for cfg,tag in [('all','all'),('allinc','allinconclusive'),('allincwin','allinconclusiveplatformwin32A'),('allincc03','allinconclusivestdc++03'),('allincc11','allinconclusivestdc++11')]:
        for l in ('c','cpp'): sets[(l,cfg)]=ids(f'/tmp/S_{l}_{tag}.xml')
    for n in d:
        ic = (n in sets[('c','allincc11')]) or (n in sets[('c','allincwin')]) or (n in sets[('c','allinc')])
        ip = (n in sets[('cpp','allincc11')]) or (n in sets[('cpp','allincwin')]) or (n in sets[('cpp','allinc')])
        lang[n]='both' if ic and ip else ('cpp' if ip else ('c' if ic else 'none'))
fixlang()
print("lang none:",[n for n,x in lang.items() if x=='none'])
EOF"}

