import re,subprocess,itertools,json,time
sevs=['style','warning','performance','portability','information','unusedFunction','missingInclude']
def run(args,f):
    return frozenset(re.findall(r'<checker id="([^"]*)"',subprocess.run(["/workspace/executable",*args,"--output-format=xmlv3",f],capture_output=True,text=True).stderr))
res={}
t0=time.time()
for lang,f in (('c','c.c'),('cpp','e.cpp')):
    for inc in (0,1):
        for mask in range(128):
            lst=[sevs[i] for i in range(7) if mask>>i&1]
            if not lst: continue
            args=["--enable="+",".join(lst)]+ (["--inconclusive"] if inc else [])
            res[(lang,inc,mask)]=run(args,f)
print("time",time.time()-t0)
json.dump({f"{k[0]}|{k[1]}|{k[2]}":sorted(v) for k,v in res.items()},open('/tmp/full.json','w'))
print("configs:",len(res))
# check monotonicity
bad=0
for lang in ('c','cpp'):
    for inc in (0,1):
        for mask in range(128):
            if not (lang,inc,mask) in res: continue
            for i in range(7):
                if mask>>i&1: continue
                m2=mask|(1<<i)
                if (lang,inc,m2) in res and not res[(lang,inc,m2)]>=res[(lang,inc,mask)]: bad+=1
print("non-monotone:",bad)
EOF"}

