for n in sorted(allnames):
    cond={}
    for lang in ('c','cpp'):
        for inc in (0,1):
            masks=[m for m in range(128) if (lang,inc,m) in d and n in d[(lang,inc,m)]]
            if not masks: cond[f"{lang}{inc}"]=None; continue
            # minimal elements
            mins=[m for m in masks if not any((m2&m)==m2 for m2 in masks if m2!=m and (m2|m)==m and m2<m)]
            # better: minimal under subset
            mins=[m for m in masks if not any(m2<m and (m2 & m)==m2 and m2!=m for m2 in masks)]
            cond[f"{lang}{inc}"]=mins
    out[n]=cond
