// Settings and command line handling for our C/C++ static analysis tool.
#pragma once
#include <set>
#include <string>
#include <vector>

// severity groups (bit indices) - 'error' is always enabled
enum Severity {
    SeverityStyle = 0,
    SeverityWarning,
    SeverityPerformance,
    SeverityPortability,
    SeverityInformation,
    SeverityUnusedFunction,
    SeverityMissingInclude,
    SeverityNone
};

struct Settings {
    // command line state
    bool quiet = false;
    bool verbose = false;
    bool force = false;
    bool inconclusive = false;
    bool safety = false;
    bool xml = false;              // --xml (deprecated xml v2 output)
    std::string outputFormat = "text";
    bool dump = false;
    bool checkConfig = false;
    bool checkLibrary = false;
    bool errorlist = false;
    bool inlineSuppr = false;
    bool fsignedChar = false;
    bool funsignedChar = false;
    bool reportProgress = false;
    int errorExitcode = 0;
    int jobs = 1;
    int loadAverage = -1;
    int maxConfigs = 12;
    int maxCtuDepth = 2;
    unsigned enabledSeverities = 0;
    bool forceMaxConfigs = false;
    std::string outputTemplate;
    std::string outputTemplateLocation;
    std::string templateName;
    std::string std_ = "c++20";
    std::string platform = "native";
    std::string language;          // forced language ("c"/"c++")
    std::string outputFileName;
    std::string plistOutput;
    std::string checkersReportFile;
    std::string buildDir;
    std::string reportType = "normal";
    std::string showtime = "none";
    std::string checkLevel = "normal";
    std::vector<std::string> defines;
    std::vector<std::string> undefines;
    std::vector<std::string> includePaths;
    std::vector<std::string> includes;      // forced includes
    std::vector<std::string> libraries;
    std::vector<std::string> addons;
    std::string addonPython;
    std::vector<std::string> fileFilters;
    std::vector<std::string> ignorePaths;   // -i
    std::vector<std::string> configExcludes;
    std::string configExcludesFile;
    std::vector<std::string> suppressions;
    std::string suppressionsList;
    std::string suppressXml;
    std::string exitcodeSuppressions;
    std::string projectFile;
    std::vector<std::string> projectConfigurations;
    std::string clangExec;
    std::vector<std::string> relativePaths;
    bool relativePathsSet = false;

    bool isEnabled(Severity s) const {
        if (s == SeverityStyle) return true; // not used
        return (enabledSeverities & (1u << s)) != 0;
    }
    // 'error' severity is always enabled
    bool severityEnabled(const std::string& sev) const {
        if (sev == "error") return true;
        if (sev == "style") return (enabledSeverities & (1u << SeverityStyle)) != 0;
        if (sev == "warning") return (enabledSeverities & (1u << SeverityWarning)) != 0;
        if (sev == "performance") return (enabledSeverities & (1u << SeverityPerformance)) != 0;
        if (sev == "portability") return (enabledSeverities & (1u << SeverityPortability)) != 0;
        if (sev == "information") return (enabledSeverities & (1u << SeverityInformation)) != 0;
        if (sev == "unusedFunction") return (enabledSeverities & (1u << SeverityUnusedFunction)) != 0;
        if (sev == "missingInclude") return (enabledSeverities & (1u << SeverityMissingInclude)) != 0;
        return true;
    }
    bool isCplusplus() const { return language == "c++" || (language.empty() && std_.rfind("c++", 0) == 0); }
    bool isCpp03() const { return std_ == "c++03"; }
    bool isWindowsPlatform() const { return platform.rfind("win", 0) == 0; }
};
