#include <algorithm>
#include <cctype>
#include <sys/stat.h>
#include <dirent.h>
#include <unistd.h>

namespace pathutil {

inline bool isDirectory(const std::string& p)
{
    struct stat st;
    if (stat(p.c_str(), &st) != 0) return false;
    return S_ISDIR(st.st_mode);
}

inline bool exists(const std::string& p)
{
    struct stat st;
    return stat(p.c_str(), &st) == 0;
}

inline std::string toLower(std::string s)
{
    std::transform(s.begin(), s.end(), s.begin(), [](unsigned char c) { return (char)std::tolower(c); });
    return s;
}

// extension without dot, lowercased
inline std::string getExtensionLower(const std::string& p)
{
    const std::size_t pos = p.find_last_of('.');
    if (pos == std::string::npos) return "";
    return toLower(p.substr(pos + 1));
}

inline std::string stripLeadingDashDash(const std::string& s)
{
    if (s.size() > 1 && s[0] == '-' && s[1] == '-') return s.substr(2);
    return s;
}

// ---------------------------------------------------------------------------
// Pattern matching used by --file-filter and -i (ignore).
// A pattern is a '/' separated sequence of components. Each component is
// matched against one component of the path with '*' and '?' wildcards that
// never cross a '/'. The pattern matches when its components form a
// contiguous subsequence of the path components.
// ---------------------------------------------------------------------------
inline bool matchComponent(const char* pat, const char* str)
{
    while (*pat) {
        if (*pat == '*') {
            ++pat;
            if (!*pat) return true; // '*' matches the rest
            for (const char* s = str; ; ++s) {
                if (matchComponent(pat, s)) return true;
                if (!*s || *s == '/') return false;
            }
        } else if (*pat == '?') {
            if (!*str || *str == '/') return false;
            ++pat; ++str;
        } else {
            if (*pat != *str) return false;
            ++pat; ++str;
        }
    }
    return *str == '\0';
}

inline bool matchesPattern(const std::string& pattern, const std::string& path)
{
    if (pattern.empty()) return false;
    std::vector<std::string> pat;
    std::vector<std::string> pat2;
    // split, keeping an empty leading component for absolute paths
    {
        std::size_t i = 0;
        while (i < pattern.size()) {
            std::size_t j = pattern.find('/', i);
            if (j == std::string::npos) { pat.push_back(pattern.substr(i)); break; }
            pat.push_back(pattern.substr(i, j - i));
            i = j + 1;
        }
    }
    std::vector<std::string> comps;
    {
        std::size_t i = 0;
        while (i < path.size()) {
            std::size_t j = path.find('/', i);
            if (j == std::string::npos) { comps.push_back(path.substr(i)); break; }
            comps.push_back(path.substr(i, j - i));
            i = j + 1;
        }
    }
    if (pat.size() > comps.size()) return false;
    const std::size_t maxStart = comps.size() - pat.size();
    for (std::size_t start = 0; start <= maxStart; ++start) {
        bool ok = true;
        for (std::size_t k = 0; k < pat.size() && ok; ++k)
            ok = matchComponent(pat[k].c_str(), comps[start + k].c_str());
        if (ok) return true;
    }
    return false;
}

inline std::string nativeSeparators(std::string s)
{
    (void)s;
    return s;
}

} // namespace pathutil
