#pragma once
#include "settings.h"
#include <cstdio>
#include <iostream>
#include <fstream>
#include <sstream>

struct CommandLine {
    bool help = false;
    bool version = false;
    std::vector<std::string> paths;   // raw paths from the command line / file list
    bool ok = false;
};

void cmdError(const std::string& msg)
{
    std::cerr << "cppcheck: error: " << msg << std::endl;
}

static void splitList(const std::string& s, std::vector<std::string>& out)
{
    std::string cur;
    for (char c : s) {
        if (c == ',') { out.push_back(cur); cur.clear(); }
        else cur += c;
    }
    out.push_back(cur);
}

// returns severity bitmask; throws nothing
static bool enableSeverity(Settings& s, const std::string& name, bool enable)
{
    unsigned bit = 0;
    if (name == "style") bit = 1u << SeverityStyle;
    else if (name == "warning") bit = 1u << SeverityWarning;
    else if (name == "performance") bit = 1u << SeverityPerformance;
    else if (name == "portability") bit = 1u << SeverityPortability;
    else if (name == "information") bit = 1u << SeverityInformation;
    else if (name == "unusedFunction") bit = 1u << SeverityUnusedFunction;
    else if (name == "missingInclude") bit = 1u << SeverityMissingInclude;
    else if (name == "all") {
        unsigned all = (1u << SeverityStyle) | (1u << SeverityWarning) | (1u << SeverityPerformance) |
                       (1u << SeverityPortability) | (1u << SeverityInformation) |
                       (1u << SeverityUnusedFunction) | (1u << SeverityMissingInclude);
        if (enable) s.enabledSeverities |= all; else s.enabledSeverities &= ~all;
        return true;
    } else return false;
    if (enable) s.enabledSeverities |= bit;
    else s.enabledSeverities &= ~bit;
    return true;
}

static bool toInt(const std::string& s, int& out)
{
    if (s.empty()) return false;
    std::size_t i = 0;
    bool neg = false;
    if (s[0] == '+' || s[0] == '-') { neg = (s[0] == '-'); i = 1; if (s.size() == 1) return false; }
    for (; i < s.size(); ++i)
        if (s[i] < '0' || s[i] > '9') return false;
    long long v = 0;
    for (char c : s) if (c >= '0' && c <= '9') v = v * 10 + (c - '0');
    if (neg) v = -v;
    if (v > 2147483647LL) v = 2147483647LL;
    if (v < -2147483648LL) v = -2147483648LL;
    out = (int)v;
    return true;
}
