static bool parseShortOpt(const std::string& arg, int argc, const char* const argv[], int& i, Settings& s, bool& ret)
{
    char c = arg[1];
    const std::string attached = arg.size() > 2 ? arg.substr(2) : std::string();
    auto missing = [&](const char* opt) { cmdError(std::string("argument to '") + opt + "' is missing."); return false; };
    if (c == 'h') { ret = true; return true; } // handled by pre-scan too
    if (c == 'v') { s.verbose = true; return true; }
    if (c == 'q') { s.quiet = true; return true; }
    if (c == 'f') { s.force = true; s.forceMaxConfigs = true; return true; }
    if (c == 'E') { s.preprocessOnly = true; return true; }
    if (c == 'r') {
        if (arg.compare(0, 4, "-rp=") == 0) {
            s.relativePathsSet = true;
            const std::string val = arg.substr(4);
            std::string cur;
            for (char ch : val) { if (ch == ';') { s.relativePaths.push_back(cur); cur.clear(); } else cur += ch; }
            s.relativePaths.push_back(cur);
            return true;
        }
        cmdError("unrecognized command line option: \"" + arg + "\".");
        return false;
    }
    if (c == 'x') {
        std::string val;
        if (!attached.empty()) { cmdError("no language given to '-x' option."); return false; }
        if (i + 1 >= argc || argv[i+1][0] == '-') { cmdError("no language given to '-x' option."); return false; }
        val = argv[++i];
        if (val != "c" && val != "c++") { cmdError("unknown language '" + val + "' enforced."); return false; }
        s.language = val;
        return true;
    }
    if (c == 'I' || c == 'i' || c == 'j' || c == 'l' || c == 'D' || c == 'U') {
        std::string val = attached;
        if (val.empty()) {
            if (i + 1 >= argc || argv[i+1][0] == '-') {
                if (c == 'x') cmdError("no language given to '-x' option.");
                else return missing(arg.substr(0, 2).c_str());
                return false;
            }
            val = argv[++i];
        }
        switch (c) {
        case 'I': s.includePaths.push_back(val); break;
        case 'i': s.ignorePaths.push_back(val); break;
        case 'j': {
            int v = 0;
            if (!toInt(val, v)) { cmdError("argument to '-j' is not valid - not an integer."); return false; }
            if (v < 1) { cmdError("argument for '-j' must be greater than 0."); return false; }
            s.jobs = v;
            break;
