        case 'l': {
            int v = 0;
            if (!toInt(val, v)) { cmdError("argument to '-l' is not valid - not an integer."); return false; }
            s.loadAverage = v;
            break;
        }
        case 'D': s.defines.push_back(val); break;
        case 'U': s.undefines.push_back(val); break;
        }
        return true;
    }
    cmdError("unrecognized command line option: \"" + arg + "\".");
    return false;
}
