for k,v in raw.items():
    lang,inc,mask=k.split('|'); meas[(lang,int(inc),int(mask))]=set(v)
def langof(n):
    # derived empirically: active in c?
    inc_=0
    inC = any(n in meas[('c',i,m)] for i in (0,1) for m in range(128))
    inCpp = any(n in meas[('cpp',i,m)] for i in (0,1) for m in range(128))
    return 'both' if (inC and inCpp) else ('cpp' if inCpp else ('c' if inC else 'none'))
def active(n, env):
    R=req[n]
