import json,itertools
raw=json.load(open('/tmp/full.json'))
meas={}
for k,v in raw.items():
    lang,inc,mask=k.split('|'); meas[(lang,int(inc),int(mask))]=set(v)
def expand(mask):
    return mask | (1|2|4|8 if mask & 1 else 0)
# build act tables: act[checker][(lang, em, inc)]
