    act[n]={}
    for lang in ('c','cpp'):
        for inc in (0,1):
            for em in range(128):
                # find measured configs whose expanded mask == em
                found=None
                for m in range(1,128):
                    if (lang,inc,m) in meas and expand(m)==em:
                        found=(lang,inc,m); break
                if found is None:
                    act[n][(lang,em,inc)]=None   # unknown (em not reachable directly)
                else:
                    act[n][(lang,em,inc)] = n in meas[found]
json.dump({n:{str(k):v for k,v in t.items()} for n,t in act.items()},open('/tmp/act.json','w'))
# summarize how many are None
for n in list(act)[:3]: print(n, act[n])
EOF"}

