namespace report_detail {

inline std::string replaceAll(std::string s, const std::string& a, const std::string& b)
{
    if (a.empty()) return s;
    std::string out;
    std::size_t pos = 0;
    while (true) {
        const std::size_t p = s.find(a, pos);
        if (p == std::string::npos) { out += s.substr(pos); break; }
        out += s.substr(pos, p - pos);
        out += b;
        pos = p + a.size();
    }
    return out;
}

// read a single line of a file (1 based). Tabs are replaced by a single space.
inline std::string readCodeLine(const std::string& file, int line)
{
    if (line <= 0 || file.empty()) return std::string();
    std::ifstream f(file);
    if (!f.is_open()) return std::string();
    std::string l;
    for (int i = 0; i < line; ++i) {
        if (!std::getline(f, l)) return std::string();
    }
    return replaceAll(l, "\t", " ");
}

inline std::string codeField(const ErrorMessage& e)
{
    const Location& loc = e.primary();
    if (loc.line <= 0) return std::string();
    const std::string line = readCodeLine(loc.file, loc.line);
    if (line.empty() && loc.column <= 0) return line;
    std::string out = line;
    if (loc.column > 1) out += "\n" + std::string((std::size_t)(loc.column - 1), ' ');
    if (loc.column > 0) out += "^";
    return out;
}

inline std::string callStack(const ErrorMessage& e)
{
    std::string out;
    for (std::size_t i = e.locations.size(); i > 0; --i) {
        const Location& loc = e.locations[i - 1];
        if (!out.empty()) out += " -> ";
        out += "[" + loc.file + ":" + std::to_string(loc.line) + "]";
    }
    return out;
}

inline std::string render(const std::string& tpl, const ErrorMessage& e, const std::string& severity)
{
    std::string out;
    for (std::size_t i = 0; i < tpl.size();) {
        if (tpl[i] == '\\' && i + 1 < tpl.size()) {
            const char c = tpl[i + 1];
            if (c == 't') { out += '\t'; i += 2; continue; }
            if (c == 'n') { out += '\n'; i += 2; continue; }
            if (c == 'r') { out += '\r'; i += 2; continue; }
            out += tpl[i]; i++; continue;
        }
        if (tpl[i] == '{') {
            const std::size_t end = tpl.find('}', i);
            if (end != std::string::npos) {
                const std::string field = tpl.substr(i + 1, end - i - 1);
                const std::size_t colon = field.find(':');
                const std::string name = colon == std::string::npos ? field : field.substr(0, colon);
                const std::string rest = colon == std::string::npos ? std::string() : field.substr(colon + 1);
                if (name == "file") out += e.primary().file;
                else if (name == "line") out += std::to_string(e.primary().line);
                else if (name == "column") out += std::to_string(e.primary().column);
                else if (name == "callstack") out += callStack(e);
                else if (name == "inconclusive") { if (e.inconclusive) out += rest; }
                else if (name == "severity") out += severity;
                else if (name == "message") out += e.msg;
                else if (name == "id") out += e.id;
                else if (name == "cwe") out += (e.cwe ? std::to_string(e.cwe) : std::string());
                else if (name == "code") out += codeField(e);
                else out += field;
                i = end + 1;
                continue;
            }
        }
        out += tpl[i];
        i++;
    }
    return out;
}

} // namespace report_detail
