namespace report_detail {

inline std::string replaceAll(std::string s, const std::string& a, const std::string& b)
{
    if (a.empty()) return s;
    std::string out;
    std::size_t pos = 0;
    while (true) {
        const std::size_t p = s.find(a, pos);
        if (p == std::string::npos) { out += s.substr(pos); break; }
        out += s.substr(pos, p - pos);
        out += b;
        pos = p + a.size();
    }
    return out;
}

// read a single line of a file (1 based). Tabs are replaced by a single space.
inline std::string readCodeLine(const std::string& file, int line)
{
    if (line <= 0 || file.empty()) return std::string();
    std::ifstream f(file);
    if (!f.is_open()) return std::string();
    std::string l;
    for (int i = 0; i < line; ++i) {
        if (!std::getline(f, l)) return std::string();
    }
    return replaceAll(l, "\t", " ");
}

inline std::string codeField(const ErrorMessage& e)
{
    const Location& loc = e.primary();
    if (loc.line <= 0) return std::string();
    const std::string line = readCodeLine(loc.file, loc.line);
    if (line.empty() && loc.column <= 0) return line;
    std::string out = line;
    if (loc.column > 1) out += "\n" + std::string((std::size_t)(loc.column - 1), ' ');
    if (loc.column > 0) out += "^";
    return out;
}

inline std::string callStack(const ErrorMessage& e)
{
    std::string out;
    for (std::size_t i = e.locations.size(); i > 0; --i) {
        const Location& loc = e.locations[i - 1];
        if (!out.empty()) out += " -> ";
        out += "[" + loc.file + ":" + std::to_string(loc.line) + "]";
    }
    return out;
}

