#include <cstring>
#include <cstdio>

#define FILESDIR "/usr/local/share/Cppcheck"
static const char* VERSION = "Cppcheck 2.19 dev";

// ---------------------------------------------------------------------------
// progress reporting
// ---------------------------------------------------------------------------
static std::ostream* progressStream()
{
    static std::ofstream file;
    return &std::cout;
}

static void writeError(const std::string& msg, const Settings& settings, std::ostream*& errStream, std::ofstream& errFile)
{
    if (!errStream) {
        if (!settings.outputFileName.empty()) {
            errFile.open(settings.outputFileName, std::ios::app);
            if (!errFile.is_open()) {
                std::cerr << "cppcheck: error: failed to open the file: \"" << settings.outputFileName << "\"." << std::endl;
                exit(1);
            }
            errStream = &errFile;
        } else errStream = &std::cerr;
    }
    *errStream << msg << std::endl;
}

int main(int argc, char* const argv[])
{
    Settings settings;
    CommandLine cl;
    if (!parseCommandLine(argc, argv, settings, cl)) return 1;
    if (cl.help) { std::cout << HELP_TEXT; return 0; }
    if (cl.version) { std::cout << VERSION << std::endl; return 0; }
    if (settings.errorlist) { std::cout << ERRORLIST_XML; return 0; }

    // --------------------------------------------------------------- library
    // The standard library configuration is looked up in the installation
    // folder first and then in the current working directory.
    {
        std::string path = FILESDIR "/cfg/std.cfg";
        std::ifstream f(path);
        bool found = false;
        if (f.is_open()) { found = true; f.close(); }
        if (!found) {
            std::ifstream f2("std.cfg");
            if (f2.is_open()) { found = true; f2.close(); }
        }
        if (!found) {
            std::cerr << "cppcheck: Failed to load library configuration file 'std.cfg'. File not found" << std::endl;
            std::cerr << "Failed to load std.cfg. Your Cppcheck installation is broken, please re-install. "
                         "The Cppcheck binary was compiled with FILESDIR set to \"" FILESDIR "\" and will "
                         "therefore search for std.cfg in " FILESDIR "/cfg." << std::endl;
            return 1;
        }
    }

    // ------------------------------------------------------------ file lists
    std::vector<std::string> allPaths;   // raw paths in command line order
    for (const std::string& p : cl.paths) allPaths.push_back(p);

    // expand directories
    std::vector<std::string> files;
    bool ignored = false;
    for (const std::string& p : allPaths) {
        if (pathutil::isDirectory(p)) {
            // recursive search
            std::vector<std::string> dirs;
            dirs.push_back(p);
            std::vector<std::string> found;
            for (std::size_t i = 0; i < dirs.size(); ++i) {
                const std::string dir = dirs[i];
                DIR* d = opendir(dir.c_str());
                if (!d) continue;
                struct dirent* ent;
                std::vector<std::string> subdirs;
                while ((ent = readdir(d)) != nullptr) {
                    const std::string name = ent->d_name;
                    if (name == "." || name == "..") continue;
                    std::string full = dir;
                    if (!full.empty() && full[full.size()-1] != '/') full += "/";
                    full += name;
                    struct stat st;
                    if (stat(full.c_str(), &st) != 0) continue;
                    if (S_ISDIR(st.st_mode)) subdirs.push_back(full);
                    else {
                        const std::string ext = pathutil::getExtensionLower(name);
                        static const char* exts[] = {"cpp","cxx","cc","c++","c","ipp","ixx","tpp","txx"};
                        for (const char* e : exts) if (ext == e) { found.push_back(full); break; }
                    }
                }
                closedir(d);
                for (const std::string& sd : subdirs) dirs.push_back(sd);
            }
            for (const std::string& f : found) files.push_back(f);
        } else {
            files.push_back(p);
        }
    }
    // remove ignore patterns
    if (!settings.ignorePaths.empty()) {
        std::vector<std::string> keep;
        for (const std::string& f : files) {
            bool skip = false;
            for (const std::string& ig : settings.ignorePaths)
                if (pathutil::matchesPattern(ig, f)) { skip = true; break; }
            if (!skip) keep.push_back(f);
        }
        files.swap(keep);
        ignored = true;
    }
    // deduplicate, keeping the first occurrence
    {
        std::vector<std::string> out;
        std::set<std::string> seen;
        for (const std::string& f : files) if (seen.insert(f).second) out.push_back(f);
        files.swap(out);
    }
    if (files.empty()) {
        writeError("could not find or open any of the paths given.", settings, nullptr, *(std::ofstream*)nullptr);
        return 1;
    }
    // file filters
    if (!settings.fileFilters.empty()) {
        std::vector<std::string> out;
        bool anyEmpty = false;
        for (const std::string& filter : settings.fileFilters) {
            std::vector<std::string> matched;
            for (const std::string& f : files)
                if (pathutil::matchesPattern(filter, f)) matched.push_back(f);
            if (matched.empty()) { writeError("could not find any files matching the filter:" + filter, settings, nullptr, *(std::ofstream*)nullptr); anyEmpty = true; continue; }
            for (const std::string& f : matched)
                if (std::find(out.begin(), out.end(), f) == out.end()) out.push_back(f);
        }
        if (out.empty()) return 1;
        files.swap(out);
    }
    if (files.empty()) return 1;
    (void)progressStream;
    return 0;
}
