// Error output: text templates, xml, sarif, plist
#pragma once
#include "report.h"
#include <cstring>

class Reporter
{
public:
    explicit Reporter(const Settings& s) : settings(s)
    {
        if (!s.outputFileName.empty()) {
            file.open(s.outputFileName);
            if (!file.is_open()) std::cerr << "cppcheck: error: failed to open the file: \"" << s.outputFileName << "\"." << std::endl;
            stream = &file;
        } else stream = &std::cerr;
        templateText = s.outputTemplate.empty() ? "{file}:{line}:{column}: {severity}: {message} [{id}]\n{code}" : s.outputTemplate;
        if (s.outputTemplate.empty() && s.templateName.empty()) {
            // default
        } else if (s.templateName == "gcc") templateText = "{file}:{line}:{column}: warning: {message} [{id}]\n{code}";
        else if (s.templateName == "cppcheck1") templateText = "[{callstack}]: ({severity}) {message}";
        else if (s.templateName == "vs") templateText = "{file}({line}): {severity}: {message}";
        else if (s.templateName == "edit") templateText = "{file} +{line}: {severity}: {message}";
        else if (!s.outputTemplate.empty()) templateText = s.outputTemplate;
        locationTemplate = s.outputTemplateLocation.empty() ? std::string() : s.outputTemplateLocation;
        if (s.outputTemplateLocation.empty() && !s.templateName.empty()) locationTemplate.clear();
    }

    void begin()
    {
        const bool xml = isXml();
