// ---------------------------------------------------------------------------
// suppressions
// ---------------------------------------------------------------------------
struct Suppression {
    std::string id;
    std::string file;
    int line = -1;
    bool matches(const ErrorMessage& e) const
    {
        if (!id.empty() && id != "*" && id != e.id) return false;
        if (!file.empty()) {
            const std::string errFile = simplify(e.primary().file);
            const std::string supFile = simplify(file);
            if (errFile != supFile) {
                const std::string withSlash = "/" + supFile;
                if (errFile.size() <= supFile.size()) return false;
                if (errFile.compare(errFile.size() - withSlash.size(), withSlash.size(), withSlash) != 0) return false;
            }
        }
        if (line >= 0 && e.primary().line != line) return false;
        return true;
    }
    // parse "[error id]:[filename]:[line]"
    static bool parse(const std::string& spec, Suppression& out)
    {
        std::vector<std::string> parts;
        std::string cur;
        for (char c : spec) { if (c == ':') { parts.push_back(cur); cur.clear(); } else cur += c; }
        parts.push_back(cur);
        if (parts.size() > 3) return false;
        out.id = parts[0];
        if (out.id.empty()) out.id = "*";
        if (parts.size() > 1) out.file = parts[1];
        if (parts.size() > 2) {
            std::string lineStr = parts[2];
            std::size_t i = 0;
            bool neg = false;
            if (!lineStr.empty() && (lineStr[0] == '-' || lineStr[0] == '+')) { neg = lineStr[0] == '-'; i = 1; }
            while (i < lineStr.size() && lineStr[i] >= '0' && lineStr[i] <= '9') ++i;
            if (i == 0) out.line = -1;
            else {
                int v = 0;
                for (std::size_t k = 0; k < i; ++k) v = v * 10 + (lineStr[k] - '0');
                out.line = neg ? -v : v;
            }
        }
        return true;
    }
    static std::string simplify(const std::string& path)
    {
        std::vector<std::string> comps;
        std::size_t i = 0;
        bool absolute = !path.empty() && path[0] == '/';
        while (i < path.size()) {
            std::size_t j = path.find('/', i);
            if (j == std::string::npos) { comps.push_back(path.substr(i)); break; }
            comps.push_back(path.substr(i, j - i));
            i = j + 1;
        }
        std::vector<std::string> out;
        for (const std::string& c : comps) {
            if (c == "." || c.empty()) continue;
            out.push_back(c);
        }
        std::string res;
        for (const std::string& c : out) { if (!res.empty()) res += "/"; res += c; }
        if (absolute) res = "/" + res;
        return res;
    }
};
