{"command": "cat > /workspace/src/main.cpp <<'EOF'
// Cppcheck-like static analysis tool (reimplementation from observed behaviour)
#include "gen/help.txt.h"
#include "gen/errorlist.h"
#include "gen/checkers2.h"
#include "cli.h"
#include "report.h"
#include "reporter.h"
#include "analyze.h"
#include <algorithm>
#include <cstring>
#include <cstdio>
#include <dirent.h>

#define FILESDIR "/usr/local/share/Cppcheck"
static const char* VERSION = "Cppcheck 2.19 dev";

static const char* kSourceExts[] = {"cpp","cxx","cc","c++","c","ipp","ixx","tpp","txx"};

static bool isSourceExt(const std::string& name)
{
    const std::string ext = pathutil::getExtensionLower(name);
    for (const char* e : kSourceExts) if (ext == e) return true;
    return false;
}

static void addFilesRecursive(const std::string& dir, std::vector<std::string>& out)
{
    std::vector<std::string> dirs;
    dirs.push_back(dir);
    for (std::size_t i = 0; i < dirs.size(); ++i) {
        const std::string d = dirs[i];
        DIR* dp = opendir(d.c_str());
        if (!dp) continue;
        std::vector<std::string> subdirs;
        struct dirent* ent;
        while ((ent = readdir(dp)) != nullptr) {
            const std::string name = ent->d_name;
            if (name == "." || name == "..") continue;
            std::string full = d;
            if (full.empty()) full = ".";
            if (full[full.size()-1] != '/') full += "/";
            full += name;
            struct stat st;
            if (stat(full.c_str(), &st) != 0) continue;
            if (S_ISDIR(st.st_mode)) subdirs.push_back(full);
            else if (isSourceExt(name)) out.push_back(full);
        }
        closedir(dp);
        for (const std::string& sd : subdirs) dirs.push_back(sd);
    }
}

// severity mask used by the checkers report
static unsigned severityMask(const Settings& s)
{
    unsigned m = 0;
    if (s.severityEnabled("style")) m |= 1;
    if (s.severityEnabled("warning")) m |= 2;
    if (s.severityEnabled("performance")) m |= 4;
    if (s.severityEnabled("portability")) m |= 8;
    if (s.severityEnabled("information")) m |= 16;
    if (s.severityEnabled("unusedFunction")) m |= 32;
    if (s.severityEnabled("missingInclude")) m |= 64;
    return m;
}

int main(int argc, char* const argv[])
{
    Settings settings;
    CommandLine cl;
    if (!parseCommandLine(argc, argv, settings, cl)) return 1;
    if (cl.help) { std::cout << HELP_TEXT; return 0; }
    if (cl.version) { std::cout << VERSION << std::endl; return 0; }
    if (settings.errorlist) { std::cout << ERRORLIST_XML; return 0; }

    // --------------------------------------------------------------- library
    {
        bool found = false;
        {
            std::ifstream f(FILESDIR "/cfg/std.cfg");
            if (f.is_open()) { found = true; }
        }
        if (!found) {
            std::ifstream f("std.cfg");
            if (f.is_open()) found = true;
        }
        if (!found) {
            std::cerr << "cppcheck: Failed to load library configuration file 'std.cfg'. File not found" << std::endl;
            std::cerr << "Failed to load std.cfg. Your Cppcheck installation is broken, please re-install. "
                         "The Cppcheck binary was compiled with FILESDIR set to \"" FILESDIR "\" and will "
                         "therefore search for std.cfg in " FILESDIR "/cfg." << std::endl;
            return 1;
        }
    }
    for (const std::string& lib : settings.libraries) {
        bool found = false;
        std::ifstream f(lib);
        if (f.is_open()) { found = true; }
        if (!found) {
            std::cerr << "cppcheck: Failed to load library configuration file '" << lib << "'. File not found" << std::endl;
            return 1;
        }
    }

    // ---------------------------------------------------------- collect files
    std::vector<std::string> files;
    for (const std::string& p : cl.paths) {
        if (pathutil::isDirectory(p)) addFilesRecursive(p, files);
        else files.push_back(p);
    }
    if (!settings.ignorePaths.empty()) {
        std::vector<std::string> keep;
        for (const std::string& f : files) {
            bool skip = false;
            for (const std::string& ig : settings.ignorePaths)
                if (pathutil::matchesPattern(ig, f)) { skip = true; break; }
            if (!skip) keep.push_back(f);
        }
        files.swap(keep);
    }
    {
        std::vector<std::string> out;
        std::set<std::string> seen;
        for (const std::string& f : files) if (seen.insert(f).second) out.push_back(f);
        files.swap(out);
    }
    if (files.empty()) {
        std::cerr << "cppcheck: error: could not find or open any of the paths given." << std::endl;
        if (!settings.ignorePaths.empty())
            std::cerr << "cppcheck: Maybe all paths were ignored?" << std::endl;
        return 1;
    }
    if (!settings.fileFilters.empty()) {
        std::vector<std::string> out;
        for (const std::string& filter : settings.fileFilters) {
            std::vector<std::string> matched;
            for (const std::string& f : files)
