#include "analyze.h"
#include "preproc.h"
#include "reporter.h"
#include <cctype>
#include <fstream>
#include <sstream>
#include <cstring>
#include <algorithm>

// ---------------------------------------------------------------------------
// helpers
// ---------------------------------------------------------------------------
static bool isIdentStart(char c) { return std::isalpha((unsigned char)c) || c == '_'; }
static bool isIdentChar(char c) { return std::isalnum((unsigned char)c) || c == '_'; }
static bool isDigitCh(char c) { return c >= '0' && c <= '9'; }

bool isIntegerLiteral(const std::string& s, long long& v)
{
    if (s.empty()) return false;
    std::size_t i = 0;
    bool neg = false;
    std::string t = s;
    while (!t.empty() && (t[0]=='u'||t[0]=='U'||t[0]=='l'||t[0]=='L')) t = t.substr(1);
    // strip suffix at the end
    while (!t.empty() && (t.back()=='u'||t.back()=='U'||t.back()=='l'||t.back()=='L')) t.pop_back();
    if (t.empty()) return false;
    i = 0;
    if (t[0]=='-'||t[0]=='+') { neg = t[0]=='-'; i = 1; if (t.size()==1) return false; }
    if (i+1 < t.size() && t[i]=='0' && (t[i+1]=='x'||t[i+1]=='X')) {
        i += 2;
        if (i >= t.size()) return false;
        unsigned long long val = 0;
        for (; i < t.size(); ++i) {
            char c = t[i];
            int d;
            if (c>='0'&&c<='9') d = c-'0';
            else if (c>='a'&&c<='f') d = c-'a'+10;
            else if (c>='A'&&c<='F') d = c-'A'+10;
            else return false;
            val = val*16 + (unsigned long long)d;
        }
        v = (long long)val;
        return true;
    }
    long long val = 0;
    bool oct = false;
    if (i < t.size() && t[i]=='0' && i+1 < t.size()) oct = true;
    for (; i < t.size(); ++i) {
        char c = t[i];
        if (!isDigitCh(c)) return false;
        if (oct && c > '7') return false;
        val = val * (oct?8:10) + (c - '0');
    }
