    while (!t.empty() && (t[0]=='u'||t[0]=='U'||t[0]=='l'||t[0]=='L')) t = t.substr(1);
    // strip suffix at the end
    while (!t.empty() && (t.back()=='u'||t.back()=='U'||t.back()=='l'||t.back()=='L')) t.pop_back();
    if (t.empty()) return false;
    i = 0;
    if (t[0]=='-'||t[0]=='+') { neg = t[0]=='-'; i = 1; if (t.size()==1) return false; }
    if (i+1 < t.size() && t[i]=='0' && (t[i+1]=='x'||t[i+1]=='X')) {
        i += 2;
        if (i >= t.size()) return false;
        unsigned long long val = 0;
        for (; i < t.size(); ++i) {
            char c = t[i];
            int d;
            if (c>='0'&&c<='9') d = c-'0';
            else if (c>='a'&&c<='f') d = c-'a'+10;
            else if (c>='A'&&c<='F') d = c-'A'+10;
            else return false;
            val = val*16 + (unsigned long long)d;
        }
        v = (long long)val;
        return true;
    }
    long long val = 0;
    bool oct = false;
    if (i < t.size() && t[i]=='0' && i+1 < t.size()) oct = true;
    for (; i < t.size(); ++i) {
        char c = t[i];
        if (!isDigitCh(c)) return false;
        if (oct && c > '7') return false;
        val = val * (oct?8:10) + (c - '0');
    }
    v = neg ? -val : val;
    return true;
}

bool Library::load(const std::string& file, std::string& error) { (void)file; (void)error; return false; }

// ---------------------------------------------------------------------------
// comment stripping - comments are replaced by spaces so that columns stay valid
// ---------------------------------------------------------------------------
std::vector<SourceLine> stripComments(const std::string& code, std::vector<std::string>& origLines)
{
    origLines.clear();
    std::vector<SourceLine> out;
    std::string cur;
    int line = 1;
    bool inBlock = false;
    bool inString = false, inChar = false;
    for (std::size_t i = 0; i < code.size(); ++i) {
        const char c = code[i];
        const char next = i + 1 < code.size() ? code[i+1] : '\0';
        if (c == '\n') {
            origLines.push_back(cur);
            SourceLine sl;
            sl.text = cur;
            sl.line = line;
            out.push_back(sl);
            cur.clear();
            ++line;
            inString = inChar = false;
            continue;
        }
        if (inBlock) {
            if (c == '*' && next == '/') { cur += "  "; ++i; continue; }
            cur += (c == '\t' ? '\t' : ' ');
            continue;
        }
        if (inString) {
            cur += c;
            if (c == '\\') { if (next) { cur += next; ++i; } continue; }
            if (c == '"') inString = false;
            continue;
        }
        if (inChar) {
            cur += c;
            if (c == '\\') { if (next) { cur += next; ++i; } continue; }
            if (c == '\'') inChar = false;
            continue;
        }
        if (c == '"') { inString = true; cur += c; continue; }
        if (c == '\'') { inChar = true; cur += c; continue; }
        if (c == '/' && next == '/') {
            // line comment: replace with spaces to the end of the line
            while (i < code.size() && code[i] != '\n') { cur += ' '; ++i; }
            --i;
            continue;
        }
        if (c == '/' && next == '*') { inBlock = true; cur += "  "; ++i; continue; }
        cur += c;
    }
    if (!cur.empty()) { origLines.push_back(cur); SourceLine sl; sl.text = cur; sl.line = line; out.push_back(sl); }
    return out;
}

// join lines that end with a backslash
std::vector<SourceLine> logicalLines(const std::vector<SourceLine>& in)
{
    std::vector<SourceLine> out;
    for (std::size_t i = 0; i < in.size(); ++i) {
        std::string text = in[i].text;
        int line = in[i].line;
        while (!text.empty() && text[text.size()-1] == '\\' && i + 1 < in.size()) {
            text.pop_back();
            ++i;
            text += in[i].text;
        }
        SourceLine sl;
        sl.text = text;
        sl.line = line;
        sl.directive = false;
        std::size_t p = 0;
        while (p < text.size() && (text[p]==' '||text[p]=='\t')) ++p;
        if (p < text.size() && text[p] == '#') sl.directive = true;
        out.push_back(sl);
    }
    return out;
}

// ---------------------------------------------------------------------------
// preprocessor condition handling
// ---------------------------------------------------------------------------
static bool evalSimple(const std::string& expr, const std::map<std::string,std::string>& defs, long long& value);

// extract the tokens of an expression
static std::vector<std::string> tokenizeExpr(const std::string& s)
{
    std::vector<std::string> out;
    std::size_t i = 0;
    while (i < s.size()) {
        const char c = s[i];
        if (std::isspace((unsigned char)c)) { ++i; continue; }
        if (isIdentStart(c)) {
            std::string t;
            while (i < s.size() && isIdentChar(s[i])) t += s[i++];
            out.push_back(t);
            continue;
        }
        if (isDigitCh(c)) {
            std::string t;
            while (i < s.size() && (isIdentChar(s[i]) || s[i]=='.')) t += s[i++];
            out.push_back(t);
            continue;
        }
        // operators
        const char* two[] = {"&&","||","==","!=","<=",">=","<<",">>","##",nullptr};
        bool matched = false;
        for (int k = 0; two[k]; ++k) {
            if (s.compare(i,2,two[k])==0) { out.push_back(two[k]); i += 2; matched = true; break; }
        }
        if (matched) continue;
        out.push_back(std::string(1,c));
        ++i;
    }
    return out;
}

// substitute the defined macros of an expression, then evaluate
static bool evalSimple(const std::string& expr, const std::map<std::string,std::string>& defs, long long& value)
{
    std::vector<std::string> toks = tokenizeExpr(expr);
    // handle defined(X) / defined X
    std::vector<std::string> nt;
    for (std::size_t i = 0; i < toks.size(); ++i) {
        if (toks[i] == "defined") {
            if (i+1 < toks.size() && toks[i+1] == "(") {
                // find matching )
                std::size_t j = i+2, depth = 1;
                while (j < toks.size() && depth) { if (toks[j]=="(") ++depth; else if (toks[j]==")") --depth; ++j; }
                std::string name = (i+2 < toks.size()) ? toks[i+2] : "";
                nt.push_back(defs.count(name) ? "1" : "0");
                i = j - 1;
            } else if (i+1 < toks.size()) {
                nt.push_back(defs.count(toks[i+1]) ? "1" : "0");
                ++i;
            }
            continue;
        }
        nt.push_back(toks[i]);
    }
    // replace macro names
    std::vector<std::string> tt;
    for (const std::string& t : nt) {
        auto it = defs.find(t);
        if (it != defs.end() && isIdentStart(t[0])) {
            tt.push_back(it->second.empty() ? "0" : it->second);
        } else tt.push_back(t);
    }
    // simple recursive descent evaluation
    std::size_t pos = 0;
    bool ok = true;
    std::function<long long()> prim = [&]() -> long long {
        if (pos >= tt.size()) { ok = false; return 0; }
        std::string t = tt[pos];
        if (t == "(") {
            ++pos;
            long long v = expr();
            if (pos < tt.size() && tt[pos] == ")") ++pos;
            return v;
        }
        if (t == "!") { ++pos; return prim() ? 0 : 1; }
        if (t == "-" || t == "+") { ++pos; long long v = prim(); return t=="-"? -v : v; }
        if (t == "~") { ++pos; return ~prim(); }
        ++pos;
        long long v = 0;
        if (!isIntegerLiteral(t, v)) { ok = false; return 0; }
        return v;
    };
    (void)prim;
    // implement a tiny evaluator
    struct Ev {
        const std::vector<std::string>& t;
        std::size_t p = 0;
        bool ok = true;
        long long prim() {
            if (p >= t.size()) { ok = false; return 0; }
            std::string s = t[p];
            if (s == "(") { ++p; long long v = expr(0); if (p < t.size() && t[p]==")") ++p; return v; }
            if (s == "!") { ++p; return prim() ? 0LL : 1LL; }
            if (s == "~") { ++p; return ~prim(); }
            if (s == "-") { ++p; return -prim(); }
            if (s == "+") { ++p; return prim(); }
            ++p;
            long long v;
            if (!isIntegerLiteral(s, v)) { ok = false; return 0; }
            return v;
        }
        long long expr(int minPrec) {
            long long lhs = prim();
            while (ok) {
                if (p >= t.size()) break;
                const std::string& op = t[p];
                int prec = -1;
                if (op=="*"||op=="/"||op=="%") prec = 7;
                else if (op=="+"||op=="-") prec = 6;
                else if (op=="<<"||op==">>") prec = 5;
                else if (op=="<"||op==">"||op=="<="||op==">=") prec = 4;
                else if (op=="=="||op=="!=") prec = 3;
                else if (op=="&") prec = 2;
                else if (op=="^") prec = 1;
                else if (op=="|") prec = 1;
                else if (op=="&&") prec = 0;
                else if (op=="||") prec = -1;
                if (prec < minPrec) break;
                ++p;
                long long rhs = expr(prec+1);
                if (op=="+") lhs += rhs;
                else if (op=="-") lhs -= rhs;
                else if (op=="*") lhs *= rhs;
                else if (op=="/") { if (rhs) lhs /= rhs; else { ok=false; return 0; } }
                else if (op=="%") { if (rhs) lhs %= rhs; else { ok=false; return 0; } }
                else if (op=="<<") lhs <<= rhs;
                else if (op==">>") lhs >>= rhs;
                else if (op=="<") lhs = lhs<rhs;
                else if (op==">") lhs = lhs>rhs;
                else if (op=="<=") lhs = lhs<=rhs;
                else if (op==">=") lhs = lhs>=rhs;
                else if (op=="==") lhs = lhs==rhs;
                else if (op=="!=") lhs = lhs!=rhs;
                else if (op=="&") lhs &= rhs;
                else if (op=="^") lhs ^= rhs;
                else if (op=="|") lhs |= rhs;
                else if (op=="&&") lhs = (lhs&&rhs)?1:0;
                else if (op=="||") lhs = (lhs||rhs)?1:0;
            }
            return lhs;
        }
    } ev{tt};
    long long v = ev.expr(0);
    if (!ev.ok || ev.p != tt.size()) return false;
    value = v;
    return true;
}

int Preprocessor::evalCondition(const std::string& cond, const std::map<std::string,std::string>& defs)
{
    long long v = 0;
    if (evalSimple(cond, defs, v)) return v ? 1 : 0;
    return -1;
}

std::vector<std::string> Preprocessor::macrosInCondition(const std::string& cond)
{
    std::vector<std::string> out;
    for (const std::string& t : tokenizeExpr(cond)) {
        if (t.empty() || !isIdentStart(t[0])) continue;
        if (t == "defined" || t == "true" || t == "false") continue;
        if (std::find(out.begin(), out.end(), t) == out.end()) out.push_back(t);
    }
    return out;
}

std::string Preprocessor::conditionLabel(const std::string& cond, const std::vector<std::string>& definedMacros)
{
    (void)cond; (void)definedMacros;
    return std::string();
}
