            if (op=="*"||op=="/"||op=="%") return 7;
            if (op=="+"||op=="-") return 6;
            if (op=="<<"||op==">>") return 5;
            if (op=="<"||op==">"||op=="<="||op==">=") return 4;
            if (op=="=="||op=="!=") return 3;
            if (op=="&") return 2;
            if (op=="^") return 1;
            if (op=="|") return 1;
            if (op=="&&") return 0;
            if (op=="||") return -1;
            return -99;
        }
        long long expr(int minPrec) {
            long long lhs = prim();
            while (ok) {
                if (p >= t.size()) break;
                const std::string& op = t[p];
                const int prec = precOf(op);
                if (prec < minPrec || prec == -99) break;
                ++p;
                long long rhs = expr(prec+1);
                if (!ok) break;
                if (op=="+") lhs += rhs;
                else if (op=="-") lhs -= rhs;
                else if (op=="*") lhs *= rhs;
                else if (op=="/") { if (rhs) lhs /= rhs; else { ok=false; return 0; } }
                else if (op=="%") { if (rhs) lhs %= rhs; else { ok=false; return 0; } }
                else if (op=="<<") lhs <<= rhs;
                else if (op==">>") lhs >>= rhs;
                else if (op=="<") lhs = lhs<rhs;
                else if (op==">") lhs = lhs>rhs;
                else if (op=="<=") lhs = lhs<=rhs;
                else if (op==">=") lhs = lhs>=rhs;
                else if (op=="==") lhs = lhs==rhs;
                else if (op=="!=") lhs = lhs!=rhs;
                else if (op=="&") lhs &= rhs;
                else if (op=="^") lhs ^= rhs;
                else if (op=="|") lhs |= rhs;
                else if (op=="&&") lhs = (lhs&&rhs)?1:0;
                else if (op=="||") lhs = (lhs||rhs)?1:0;
            }
            return lhs;
        }
    };
    Ev ev(tt);
    long long v = ev.expr(0);
    if (!ev.ok || ev.p != tt.size()) return false;
    value = v;
    return true;
}

