// ---------------------------------------------------------------------------
// tokenizer
// ---------------------------------------------------------------------------
struct TokList {
    Token* first = nullptr;
    Token* last = nullptr;
    void add(Token* t)
    {
        t->prev = last;
        if (last) last->next = t; else first = t;
        last = t;
    }
};

static Token* tokenizeCode(const std::vector<SourceLine>& lines)
{
    TokList list;
    for (const SourceLine& sl : lines) {
        const std::string& text = sl.text;
        std::size_t i = 0;
        bool inString = false, inChar = false;
        while (i < text.size()) {
            const char c = text[i];
            if (std::isspace((unsigned char)c)) { ++i; continue; }
            if (c == '"') {
                std::size_t j = i + 1;
                while (j < text.size()) {
                    if (text[j] == '\\') { j += 2; continue; }
                    if (text[j] == '"') { ++j; break; }
                    ++j;
                }
                Token* t = new Token();
                t->tok = text.substr(i, j - i);
                t->line = sl.line;
                t->col = (int)i + 1;
                t->isNum = false;
                list.add(t);
                i = j;
                continue;
            }
            if (c == '\'') {
                std::size_t j = i + 1;
                while (j < text.size()) {
                    if (text[j] == '\\') { j += 2; continue; }
                    if (text[j] == '\'') { ++j; break; }
                    ++j;
                }
                Token* t = new Token();
                t->tok = text.substr(i, j - i);
                t->line = sl.line;
                t->col = (int)i + 1;
                list.add(t);
                i = j;
                continue;
            }
            if (isIdentStart(c)) {
                std::size_t j = i;
                while (j < text.size() && isIdentChar(text[j])) ++j;
                Token* t = new Token();
                t->tok = text.substr(i, j - i);
                t->line = sl.line;
                t->col = (int)i + 1;
                t->isName = true;
                list.add(t);
                i = j;
                continue;
            }
            if (isDigitCh(c) || (c == '.' && i + 1 < text.size() && isDigitCh(text[i+1]))) {
                std::size_t j = i;
                while (j < text.size() && (isIdentChar(text[j]) || text[j] == '.')) ++j;
                Token* t = new Token();
                t->tok = text.substr(i, j - i);
                t->line = sl.line;
                t->col = (int)i + 1;
                t->isNum = true;
                list.add(t);
                i = j;
                continue;
            }
            // multi character operators
            static const char* ops3[] = {"<<=",">>=","...",nullptr};
            static const char* ops2[] = {"&&","||","==","!=","<=",">=","<<",">>","+=","-=","*=","/=","%=","&=","|=","^=","->","::","++","--",nullptr};
            std::string op;
            for (int k = 0; ops3[k]; ++k)
                if (text.compare(i, 3, ops3[k]) == 0) { op = ops3[k]; break; }
            if (op.empty())
                for (int k = 0; ops2[k]; ++k)
                    if (text.compare(i, 2, ops2[k]) == 0) { op = ops2[k]; break; }
            std::size_t len = op.empty() ? 1 : op.size();
            Token* t = new Token();
            t->tok = text.substr(i, len);
            t->line = sl.line;
            t->col = (int)i + 1;
            if (t->tok == "(" || t->tok == "[" || t->tok == "{") t->linkType = t->tok[0];
            list.add(t);
            i += len;
        }
    }
    // link brackets
    std::vector<Token*> stack;
    for (Token* t = list.first; t; t = t->next) {
        if (t->linkType) stack.push_back(t);
        else if ((t->tok == ")" || t->tok == "]" || t->tok == "}") && !stack.empty()) {
            Token* o = stack.back();
            stack.pop_back();
            o->link = t;
            t->link = o;
        }
    }
    return list.first;
}

