};

static void report(AnalysisState& st, const char* id, const char* severity, const std::string& msg,
                   int cwe, const Location& loc, const std::string& symbol = std::string(),
                   const Location& loc2 = Location())
{
    ErrorMessage e;
    e.id = id;
    e.severity = severity;
    e.msg = msg;
    e.verbose = msg;
    e.cwe = cwe;
    e.locations.push_back(loc);
    if (!loc2.file.empty()) e.locations.push_back(loc2);
    if (!symbol.empty()) e.symbols.push_back(symbol);
    Reporter* r = (Reporter*)st.reporter;
    r->error(e);
}
