// ---------------------------------------------------------------------------
// macro expansion
// ---------------------------------------------------------------------------
static std::string expandMacros(const std::string& text, const std::map<std::string, Macro>& macros, int depth = 0)
{
    if (depth > 20) return text;
    std::string out;
    std::size_t i = 0;
    while (i < text.size()) {
        const char c = text[i];
        if (c == '"') {
            std::size_t j = i + 1;
            while (j < text.size()) { if (text[j]=='\\') { j+=2; continue; } if (text[j]=='"') { ++j; break; } ++j; }
            out += text.substr(i, j - i);
            i = j;
            continue;
        }
        if (c == '\'') {
            std::size_t j = i + 1;
            while (j < text.size()) { if (text[j]=='\\') { j+=2; continue; } if (text[j]=='\'') { ++j; break; } ++j; }
            out += text.substr(i, j - i);
            i = j;
            continue;
        }
        if (isIdentStart(c)) {
            std::size_t j = i;
            while (j < text.size() && isIdentChar(text[j])) ++j;
            std::string name = text.substr(i, j - i);
            auto it = macros.find(name);
            if (it == macros.end()) { out += name; i = j; continue; }
            const Macro& m = it->second;
            if (!m.isFunction) {
                out += expandMacros(m.value, macros, depth + 1);
                i = j;
                continue;
            }
            // function like macro: need '('
            std::size_t k = j;
            while (k < text.size() && std::isspace((unsigned char)text[k])) ++k;
            if (k >= text.size() || text[k] != '(') { out += name; i = j; continue; }
            // collect arguments
            std::vector<std::string> args;
            std::size_t p = k + 1;
            int depth2 = 1;
            std::string cur;
            while (p < text.size() && depth2) {
                char cc = text[p];
                if (cc == '(') { ++depth2; cur += cc; }
                else if (cc == ')') { --depth2; if (depth2) cur += cc; }
                else if (cc == ',' && depth2 == 1) { args.push_back(cur); cur.clear(); }
                else cur += cc;
                ++p;
            }
            if (!cur.empty() || !args.empty()) args.push_back(cur);
            std::string res = m.value;
            for (std::size_t ai = 0; ai < m.params.size(); ++ai) {
                const std::string& val = ai < args.size() ? args[ai] : std::string();
                out = res; // placeholder, replaced below
                std::string rep;
                std::size_t q = 0;
                while (q < res.size()) {
                    if (isIdentStart(res[q])) {
                        std::size_t r = q;
                        while (r < res.size() && isIdentChar(res[r])) ++r;
                        std::string nm = res.substr(q, r - q);
                        rep += (nm == m.params[ai]) ? val : nm;
                        q = r;
                    } else rep += res[q++];
                }
                res = rep;
            }
            out += expandMacros(res, macros, depth + 1);
            i = p;
            continue;
        }
        out += c;
        ++i;
    }
    return out;
}

// ---------------------------------------------------------------------------
// preprocessor run for one configuration
// ---------------------------------------------------------------------------
struct PrepResult {
    std::vector<SourceLine> lines;
    std::vector<std::pair<std::string, int>> errors;   // message, line
};

static PrepResult preprocess(const std::vector<SourceLine>& logical,
                             const std::map<std::string, std::string>& cliDefines,
                             const std::vector<std::string>& cliUndefines,
                             const std::set<std::string>& cfgDefined)
{
    PrepResult res;
    std::map<std::string, Macro> macros;
    std::vector<std::string> stack;   // conditional states
    for (const SourceLine& sl : logical) {
        const std::string& text = sl.text;
        std::size_t p = 0;
        while (p < text.size() && (text[p]==' '||text[p]=='\t')) ++p;
        if (p < text.size() && text[p] == '#') {
            std::size_t q = p + 1;
            while (q < text.size() && std::isspace((unsigned char)text[q])) ++q;
            std::size_t e = q;
            while (e < text.size() && isIdentChar(text[e])) ++e;
            std::string dir = text.substr(q, e - q);
            std::string rest = text.substr(e);
            if (dir == "include" || dir == "include_next" || dir == "import") {
                // includes are not resolved here; keep the line out of the token list
                continue;
            } else if (dir == "define") {
                std::size_t r = 0;
                while (r < rest.size() && std::isspace((unsigned char)rest[r])) ++r;
                std::size_t s = r;
                while (s < rest.size() && isIdentChar(rest[s])) ++s;
                std::string name = rest.substr(r, s - r);
                Macro m;
                m.name = name;
                if (s < rest.size() && rest[s] == '(') {
                    m.isFunction = true;
                    std::size_t t = s + 1;
                    std::string param;
                    while (t < rest.size() && rest[t] != ')') {
                        if (rest[t] == ',') { m.params.push_back(param); param.clear(); }
                        else if (!std::isspace((unsigned char)rest[t])) param += rest[t];
                        ++t;
                    }
                    if (!param.empty()) m.params.push_back(param);
                    if (t < rest.size()) ++t;
                    s = t;
                }
                while (s < rest.size() && std::isspace((unsigned char)rest[s])) ++s;
                m.value = rest.substr(s);
                macros[name] = m;
                continue;
            } else if (dir == "undef") {
                std::size_t r = 0;
                while (r < rest.size() && std::isspace((unsigned char)rest[r])) ++r;
                std::size_t s = r;
                while (s < rest.size() && isIdentChar(rest[s])) ++s;
                macros.erase(rest.substr(r, s - r));
                continue;
            } else if (dir == "error" || dir == "warning") {
                std::size_t r = 0;
                while (r < rest.size() && std::isspace((unsigned char)rest[r])) ++r;
                res.errors.push_back({rest.substr(r), sl.line, });
                res.errors.back().second = sl.line;
                // column: position of the directive keyword
                res.errors.back().first = std::string("#") + dir + " " + rest.substr(r);
                continue;
            } else if (dir == "pragma" || dir == "line" || dir == "endif" || dir == "else" ||
                       dir == "if" || dir == "ifdef" || dir == "ifndef" || dir == "elif") {
                // handled by the caller (config generation)
                continue;
            } else {
                continue;
            }
        }
        std::string expanded = expandMacros(text, macros);
        SourceLine out;
        out.text = expanded;
        out.line = sl.line;
        res.lines.push_back(out);
    }
    (void)cliDefines; (void)cliUndefines; (void)cfgDefined;
    return res;
}
