// contribution of a condition to the configuration label
static std::string labelForCondition(const std::string& cond, const std::string& dir)
{
    if (dir == "ifndef") return std::string();
    std::string c = cond;
    // trim
    std::size_t b = 0, e = c.size();
    while (b < e && std::isspace((unsigned char)c[b])) ++b;
    while (e > b && std::isspace((unsigned char)c[e-1])) --e;
    c = c.substr(b, e - b);
    // defined(X) or !defined(X)
    if (c.compare(0, 8, "defined(") == 0 && c[c.size()-1] == ')') return c.substr(8, c.size()-9) + "=" + c.substr(8, c.size()-9);
    if (c.compare(0, 8, "!defined(") == 0 && c[c.size()-1] == ')') return c.substr(9, c.size()-10);
    if (c.compare(0, 6, "ifdef ") == 0) return c.substr(6) + "=" + c.substr(6);
    // X == N  /  N == X
    {
        std::size_t p = c.find("==");
        if (p != std::string::npos) {
            std::string lhs = c.substr(0, p), rhs = c.substr(p + 2);
            auto trim = [](std::string t) {
                std::size_t b2 = 0, e2 = t.size();
                while (b2 < e2 && std::isspace((unsigned char)t[b2])) ++b2;
                while (e2 > b2 && std::isspace((unsigned char)t[e2-1])) --e2;
                return t.substr(b2, e2 - b2);
            };
            lhs = trim(lhs); rhs = trim(rhs);
            if (!lhs.empty() && isIdentStart(lhs[0])) return lhs + "=" + rhs;
            if (!rhs.empty() && isIdentStart(rhs[0])) return rhs + "=" + lhs;
            return std::string();
        }
    }
    // plain macro name
    if (!c.empty() && isIdentStart(c[0])) {
        bool allIdent = true;
        for (char ch : c) if (!isIdentChar(ch)) allIdent = false;
        if (allIdent) return c;
    }
    return std::string();
}

static PrepResult preprocessConfig(const std::vector<SourceLine>& logical,
                                   const std::map<std::string, std::string>& cliDefines,
                                   const std::vector<std::string>& cliUndefines,
                                   const std::set<std::string>& cfgDefined,
                                   const std::map<std::string, Macro>& fileMacros)
{
    PrepResult res;
    std::map<std::string, Macro> macros = fileMacros;
    for (const auto& kv : cliDefines) {
        Macro m;
        m.name = kv.first;
        m.value = kv.second;
        macros[m.name] = m;
    }
    for (const std::string& u : cliUndefines) macros.erase(u);
    // condition stack: each entry is {active, seenTrue, parentActive}
    struct Cond { bool active; bool taken; bool parentActive; std::string label; };
    std::vector<Cond> stack;
    bool active = true;
    for (const SourceLine& sl : logical) {
        const std::string& text = sl.text;
        std::size_t p = 0;
        while (p < text.size() && (text[p]==' '||text[p]=='\\t')) ++p;
        if (p < text.size() && text[p] == '#') {
            std::size_t q = p + 1;
            while (q < text.size() && std::isspace((unsigned char)text[q])) ++q;
            std::size_t e = q;
            while (e < text.size() && isIdentChar(text[e])) ++e;
            std::string dir = text.substr(q, e - q);
            std::string rest = text.substr(e);
            if (dir == "if" || dir == "ifdef" || dir == "ifndef") {
                Cond c;
                c.parentActive = active;
                std::string cond;
                if (dir == "ifdef" || dir == "ifndef") {
                    std::size_t r = 0;
                    while (r < rest.size() && std::isspace((unsigned char)rest[r])) ++r;
                    std::size_t s = r;
                    while (s < rest.size() && isIdentChar(rest[s])) ++s;
                    cond = rest.substr(r, s - r);
                } else cond = rest;
                std::map<std::string, std::string> defs;
                for (const auto& kv : macros) {
                    if (kv.second.isFunction) continue;
                    defs[kv.first] = kv.second.value;
                }
                for (const std::string& d : cfgDefined) if (!defs.count(d)) defs[d] = d;
                int v = Preprocessor::evalCondition(dir == "ifdef" ? "defined(" + cond + ")" :
                                                    (dir == "ifndef" ? "!defined(" + cond + ")" : cond), defs);
                c.active = c.parentActive && (v != 0);
                c.taken = (v != 0);
                if (c.active && c.parentActive) {
                    std::string l = labelForCondition(dir == "ifdef" ? cond : cond, dir);
                    if (!l.empty()) { if (!res.label.empty()) res.label += ";"; res.label += l; }
                }
                stack.push_back(c);
                active = c.active;
                continue;
            } else if (dir == "elif") {
                if (stack.empty()) continue;
                Cond& c = stack.back();
                bool wasTaken = c.taken;
                std::map<std::string, std::string> defs;
                for (const auto& kv : macros) { if (kv.second.isFunction) continue; defs[kv.first] = kv.second.value; }
                for (const std::string& d : cfgDefined) if (!defs.count(d)) defs[d] = d;
                int v = wasTaken ? 0 : Preprocessor::evalCondition(rest, defs);
                if (v != 0) c.taken = true;
                c.active = c.parentActive && (v != 0);
                if (c.active) {
                    std::string l = labelForCondition(rest, "if");
                    if (!l.empty()) { if (!res.label.empty()) res.label += ";"; res.label += l; }
                }
                active = c.active;
                continue;
            } else if (dir == "else") {
                if (stack.empty()) continue;
                Cond& c = stack.back();
                c.active = c.parentActive && !c.taken;
                if (c.active) c.taken = true;
                active = c.active;
                continue;
            } else if (dir == "endif") {
                if (!stack.empty()) stack.pop_back();
                active = stack.empty() ? true : stack.back().active;
                continue;
            } else if (dir == "error" || dir == "warning") {
                if (active) {
                    std::size_t r = 0;
                    while (r < rest.size() && std::isspace((unsigned char)rest[r])) ++r;
                    res.errorMsg = "#" + dir + " " + rest.substr(r);
                    res.errorLine = sl.line;
                    res.errorCol = (int)q + 1;
                    res.hasError = true;
                }
                continue;
            } else if (dir == "define") {
                if (!active) continue;
                std::size_t r = 0;
                while (r < rest.size() && std::isspace((unsigned char)rest[r])) ++r;
                std::size_t s = r;
                while (s < rest.size() && isIdentChar(rest[s])) ++s;
                std::string name = rest.substr(r, s - r);
                Macro m;
                m.name = name;
                if (s < rest.size() && rest[s] == '(') {
                    m.isFunction = true;
                    std::size_t t = s + 1;
                    std::string param;
                    while (t < rest.size() && rest[t] != ')') {
                        if (rest[t] == ',') { m.params.push_back(param); param.clear(); }
                        else if (!std::isspace((unsigned char)rest[t])) param += rest[t];
                        ++t;
                    }
                    if (!param.empty()) m.params.push_back(param);
                    if (t < rest.size()) ++t;
                    s = t;
                }
                while (s < rest.size() && std::isspace((unsigned char)rest[s])) ++s;
                m.value = rest.substr(s);
                macros[name] = m;
                continue;
            } else if (dir == "undef") {
                if (!active) continue;
                std::size_t r = 0;
                while (r < rest.size() && std::isspace((unsigned char)rest[r])) ++r;
                std::size_t s = r;
                while (s < rest.size() && isIdentChar(rest[s])) ++s;
                macros.erase(rest.substr(r, s - r));
                continue;
            } else {
                continue;
            }
        }
        if (!active) continue;
        std::string expanded = expandMacros(text, macros);
        SourceLine out;
        out.text = expanded;
        out.line = sl.line;
        res.lines.push_back(out);
    }
    return res;
}

// enumerate the configurations of a file
static std::vector<std::set<std::string> > configCombinations(const std::vector<SourceLine>& logical,
                                                              const std::map<std::string, std::string>& cliDefines)
{
    std::vector<std::string> axes;
    for (const SourceLine& sl : logical) {
        const std::string& text = sl.text;
        std::size_t p = 0;
        while (p < text.size() && (text[p]==' '||text[p]=='\\t')) ++p;
        if (p >= text.size() || text[p] != '#') continue;
        std::size_t q = p + 1;
        while (q < text.size() && std::isspace((unsigned char)text[q])) ++q;
        std::size_t e = q;
        while (e < text.size() && isIdentChar(text[e])) ++e;
        std::string dir = text.substr(q, e - q);
        if (dir != "if" && dir != "ifdef" && dir != "ifndef" && dir != "elif") continue;
        std::string rest = text.substr(e);
        std::string cond;
        if (dir == "ifdef" || dir == "ifndef") {
            std::size_t r = 0;
            while (r < rest.size() && std::isspace((unsigned char)rest[r])) ++r;
            std::size_t s = r;
            while (s < rest.size() && isIdentChar(rest[s])) ++s;
            cond = rest.substr(r, s - r);
        } else cond = rest;
        for (const std::string& m : Preprocessor::macrosInCondition(cond)) {
            if (cliDefines.count(m)) continue;
            if (std::find(axes.begin(), axes.end(), m) == axes.end()) axes.push_back(m);
        }
    }
    std::vector<std::set<std::string> > out;
    const std::size_t maxAxes = 10;
    if (axes.size() > maxAxes) axes.resize(maxAxes);
    const std::size_t n = axes.size();
    for (std::size_t mask = 0; mask < (1u << n); ++mask) {
        std::set<std::string> cfg;
        for (std::size_t i = 0; i < n; ++i) if (mask & (1u << i)) cfg.insert(axes[i]);
        out.push_back(cfg);
        if (out.size() >= 64) break;
    }
    return out;
}
