// ---------------------------------------------------------------------------
// parse and check
// ---------------------------------------------------------------------------
static bool isKeywordTok(const std::string& s)
{
    static const char* kw[] = {"if","else","for","while","do","switch","case","default","return",
        "break","continue","goto","sizeof","new","delete","throw","try","catch","typedef","using",
        "namespace","template","operator","this","public","private","protected","virtual","friend",
        "explicit","static_cast","const_cast","reinterpret_cast","dynamic_cast","true","false","NULL",
        "asm","__asm","__attribute__","__extension__","and","or","not","xor","bitand","bitor","compl",
        "not_eq","and_eq","or_eq","xor_eq","alignof","alignas","static_assert","decltype","noexcept",
        "constexpr","consteval","constinit","nullptr","__null","__typeof__","typeof","_Alignof",nullptr};
    for (int i = 0; kw[i]; ++i) if (s == kw[i]) return true;
    return false;
}

static bool isTypeQualifier(const std::string& s)
{
    static const char* q[] = {"const","static","register","extern","volatile","auto","inline","__inline",
        "__inline__","__restrict","restrict","__const","mutable","thread_local","constexpr","signed",
        "unsigned","long","short","struct","union","enum","class","typename","__signed__","__unsigned__",nullptr};
    for (int i = 0; q[i]; ++i) if (s == q[i]) return true;
    return false;
}

static bool isBuiltinType(const std::string& s)
{
    static const char* t[] = {"void","char","short","int","long","float","double","bool","_Bool",
        "__builtin_va_list","size_t","ssize_t","wchar_t","char16_t","char32_t","__int128","__float128",nullptr};
    for (int i = 0; t[i]; ++i) if (s == t[i]) return true;
    return false;
}

// Parse a type declaration starting at 't'. Returns the token of the declared
// name or nullptr when this is not a declaration.
struct DeclResult {
    Token* nameTok = nullptr;
    Token* end = nullptr;      // token after the declarator
    std::string type;
    bool isPointer = false;
    bool isReference = false;
    bool isArray = false;
    long long arraySize = -1;
    bool isConst = false;
    bool isStatic = false;
    bool isStruct = false;
    std::string structName;
};

static DeclResult parseDecl(Token* t, const std::set<std::string>& typeNames, int maxTokens = 8)
{
    DeclResult r;
    Token* p = t;
    int n = 0;
    std::string type;
    while (p && n < maxTokens) {
        if (isTypeQualifier(p->tok)) {
            if (p->tok == "const") r.isConst = true;
            if (p->tok == "static") r.isStatic = true;
            if (p->tok == "struct" || p->tok == "class" || p->tok == "union" || p->tok == "enum") {
                r.isStruct = true;
                Token* q = p->next;
                if (q && q->isName && !isTypeQualifier(q->tok) && !isBuiltinType(q->tok)) {
                    r.structName = q->tok;
                    type = q->tok;
                    p = q->next;
                    ++n;
                    continue;
                }
            }
            p = p->next;
            ++n;
            continue;
        }
        if (p->tok == "*" ) { r.isPointer = true; p = p->next; ++n; continue; }
        if (p->tok == "&") { r.isReference = true; p = p->next; ++n; continue; }
        break;
    }
    if (r.structName.empty() && p && p->isName && (isBuiltinType(p->tok) || typeNames.count(p->tok))) {
        type = p->tok;
        p = p->next;
    }
    if (type.empty()) return r;
    r.type = type;
    // optional */&
    while (p && (p->tok == "*" || p->tok == "&")) {
        if (p->tok == "*") r.isPointer = true;
        else r.isReference = true;
        p = p->next;
    }
    if (!p || !p->isName || isKeywordTok(p->tok) || isTypeQualifier(p->tok)) return DeclResult();
    r.nameTok = p;
    Token* after = p->next;
    if (!after) return DeclResult();
    if (after->tok == "[") {
        r.isArray = true;
        Token* idx = after->next;
        if (idx && idx->isNum && isIntegerLiteral(idx->tok, r.arraySize)) { /* ok */ }
        Token* close = after->link;
        r.end = close ? close->next : after->next;
    } else if (after->tok == ";" || after->tok == "=" || after->tok == "," || after->tok == ")") {
        r.end = after;
    } else return DeclResult();
    return r;
}
