struct ScopeInfo {
    std::vector<FuncInfo> funcs;
    std::map<Token*, Token*> bodyOf;      // '{' -> '}'
    std::vector<std::pair<Token*,Token*> > bodies;
    std::set<Token*> insideBody;
    std::vector<StructInfo> structs;
    std::set<std::string> typeNames;
    std::vector<VarInfo> vars;
    std::map<std::string, long long> constVars;   // variable -> known constant value
    std::map<std::string, int> constCount;
};

// evaluate a simple integer expression
static bool evalConstExpr(Token* start, Token* end, const ScopeInfo& si, long long& value)
{
    // collect tokens
    std::vector<Token*> toks;
