// ---------------------------------------------------------------------------
// one translation unit: parse and run the checks
// ---------------------------------------------------------------------------
struct Var2 {
    std::string name;
    std::string type;
    bool isArray = false;
    long long arraySize = -1;
    bool isPointer = false;
    bool isStruct = false;
    bool isConst = false;
    bool isParam = false;
    bool isGlobal = false;
    int declLine = 0, declCol = 0;
    Token* declTok = nullptr;
    bool assigned = false;
    bool read = false;
    bool used = false;
    Token* assignTok = nullptr;   // '=' token of the first assignment
    bool addrTaken = false;
    bool inFunction = false;
    std::string structName;
};

struct Func2 {
    std::string name;
    int line = 0, col = 0;
    bool isDefinition = false;
    bool returnsVoid = false;
    Token* body = nullptr;
};

struct Struct2 {
    std::string name;
    std::vector<std::pair<std::string, Location> > members;
};

struct TU {
    std::vector<Var2> vars;
    std::vector<Func2> funcs;
    std::vector<Struct2> structs;
    std::set<std::string> typeNames;
    std::map<std::string, int> constVal;      // name -> constant value
    std::map<std::string, int> constCount;
    std::map<Token*, Var2*> declNameTokens;
};

static void analyseTU(const std::string& file, const std::vector<SourceLine>& lines,
                      Reporter& rep, const Settings& settings,
                      std::set<std::string>& functionNames, std::set<std::string>& calledFunctions,
                      bool& criticalError)
{
    Token* first = tokenizeCode(lines);
    if (!first) return;
    TU tu;

    // ---- struct definitions
    for (Token* t = first; t; t = t->next) {
        if (t->tok != "struct" && t->tok != "class" && t->tok != "union") continue;
        Token* n = t->next;
        if (!n || !n->isName || n->tok == "{") continue;
        Token* brace = n->next;
        if (!brace || brace->tok != "{") continue;
        Struct2 s;
        s.name = n->tok;
        tu.typeNames.insert(n->tok);
        for (Token* m = brace->next; m && m != brace->link; m = m->next) {
            DeclResult d = parseDecl(m, tu.typeNames, 6);
            if (d.nameTok) {
                s.members.push_back({d.nameTok->tok, Location(file, d.nameTok->line, d.nameTok->col)});
                while (m && m->tok != ";" && m != brace->link) m = m->next;
                if (!m) break;
            }
        }
        tu.structs.push_back(s);
    }
    for (Token* t = first; t; t = t->next) {
        if (t->tok == "typedef") {
            for (Token* q = t->next; q && q->tok != ";"; q = q->next) if (q->isName) tu.typeNames.insert(q->tok);
        }
    }

    // ---- function definitions
    for (Token* t = first; t; t = t->next) {
        if (!t->isName || isKeywordTok(t->tok)) continue;
        if (t->prev && (t->prev->tok == "." || t->prev->tok == "->" || t->prev->tok == "::")) continue;
        if (t->next && t->next->tok == "(" && t->next->link) {
            Token* close = t->next->link;
            Token* after = close->next;
            if (after && after->tok == "{") {
                Func2 f;
                f.name = t->tok;
                f.line = t->line;
                f.col = t->col;
                f.body = after;
                f.isDefinition = true;
                Token* p = t->prev;
                bool voidRet = false;
                while (p && (isTypeQualifier(p->tok) || p->tok == "*" || p->tok == "&")) {
                    if (p->tok == "void") voidRet = true;
                    p = p->prev;
                }
                if (p && p->tok == "void") voidRet = true;
                f.returnsVoid = voidRet;
                tu.funcs.push_back(f);
            }
        }
    }
    // tokens inside function bodies
    std::set<Token*> inFunc;
    for (const Func2& f : tu.funcs) {
        if (!f.body) continue;
        for (Token* t = f.body->next; t && t != f.body->link; t = t->next) inFunc.insert(t);
    }

    // ---- declarations (globals first, then locals inside bodies, in order)
    std::map<std::string, Var2*> current;   // name -> visible declaration
    std::map<std::string, int> paramDepth;
    for (Token* t = first; t; t = t->next) {
        if (!t->isName) continue;
        if (isKeywordTok(t->tok) || isTypeQualifier(t->tok)) continue;
        if (t->next && t->next->tok == "(" && t->next->link && t->next->link->next && t->next->link->next->tok == "{") continue; // function name
        DeclResult d = parseDecl(t, tu.typeNames, 8);
        if (!d.nameTok) continue;
        Var2 v;
        v.name = d.nameTok->tok;
        v.type = d.type;
        v.isArray = d.isArray;
        v.arraySize = d.arraySize;
        v.isPointer = d.isPointer;
        v.isStruct = d.isStruct;
        v.isConst = d.isConst;
        v.declLine = d.nameTok->line;
        v.declCol = d.nameTok->col;
        v.declTok = d.nameTok;
        v.inFunction = inFunc.count(d.nameTok) != 0;
        v.isGlobal = !v.inFunction;
        tu.vars.push_back(v);
        tu.declNameTokens[d.nameTok] = &tu.vars.back();
        current[d.nameTok->tok] = &tu.vars.back();
        // skip the rest of the declaration to avoid nested matches
        Token* q = d.nameTok;
        while (q && q->tok != ";" && q->tok != "{" && q->tok != "}" && q->tok != ")") q = q->next;
        if (q && q != d.nameTok) t = q->prev;
    }
    // function parameters
    for (const Func2& f : tu.funcs) {
        if (!f.body) continue;
        Token* open = f.body->prev;      // ')'
        Token* pstart = open ? open->link : nullptr;   // '('
        if (!pstart) continue;
        for (Token* t = pstart->next; t && t != open; t = t->next) {
            if (!t->isName || isKeywordTok(t->tok) || isTypeQualifier(t->tok)) continue;
            DeclResult d = parseDecl(t, tu.typeNames, 6);
            if (!d.nameTok) continue;
            Var2 v;
            v.name = d.nameTok->tok;
            v.type = d.type;
            v.isArray = d.isArray;
            v.arraySize = d.arraySize;
            v.isPointer = d.isPointer;
            v.isStruct = d.isStruct;
            v.isConst = d.isConst;
            v.declLine = d.nameTok->line;
            v.declCol = d.nameTok->col;
            v.declTok = d.nameTok;
            v.isParam = true;
            v.inFunction = true;
            tu.vars.push_back(v);
            tu.declNameTokens[d.nameTok] = &tu.vars.back();
            current[d.nameTok->tok] = &tu.vars.back();
            while (t && t->tok != "," && t != open) t = t->next;
            if (!t || t == open) break;
        }
    }

    // ---- walk the tokens: assignments and reads
    std::set<std::string> usedMembers;
    for (Token* t = first; t; t = t->next) {
        if (!t->isName) continue;
        auto dn = tu.declNameTokens.find(t);
        bool isDeclName = (dn != tu.declNameTokens.end());
        auto it = current.find(t->tok);
        if (it == current.end()) {
            // maybe a function call
            if (t->next && t->next->tok == "(") calledFunctions.insert(t->tok);
            continue;
        }
        Var2* v = it->second;
        if (isDeclName && tu.declNameTokens[t] == v) {
            // declaration: handle the initializer
            Token* nx = t->next;
            if (nx && nx->tok == "=") {
                v->assigned = true;
                v->assignTok = nx;
                // constant propagation
                long long val;
                if (nx->next && nx->next->isNum && isIntegerLiteral(nx->next->tok, val) &&
                    tu.constCount.find(v->name) == tu.constCount.end()) {
                    tu.constVal[v->name] = (int)val;
                    tu.constCount[v->name] = 1;
                }
            }
            continue;
        }
        if (isDeclName) continue;
        v->used = true;
        Token* nx = t->next;
        if (nx && (nx->tok == "=" || nx->tok == "+=" || nx->tok == "-=" || nx->tok == "*=" ||
                   nx->tok == "/=" || nx->tok == "%=" || nx->tok == "&=" || nx->tok == "|=" ||
                   nx->tok == "^=" || nx->tok == "<<=" || nx->tok == ">>=")) {
            if (nx->tok == "=") {
                if (!v->assigned) {
                    v->assigned = true;
                    v->assignTok = nx;
                    long long val;
                    if (nx->next && nx->next->isNum && isIntegerLiteral(nx->next->tok, val) &&
                        tu.constCount.find(v->name) == tu.constCount.end()) {
                        tu.constVal[v->name] = (int)val;
                        tu.constCount[v->name] = 1;
                    }
                }
            } else {
                v->assigned = true;
                v->read = true;
            }
            continue;
        }
        if (nx && (nx->tok == "++" || nx->tok == "--")) { v->assigned = true; v->read = true; continue; }
        if (t->prev && (t->prev->tok == "++" || t->prev->tok == "--")) { v->assigned = true; v->read = true; continue; }
        if (t->prev && t->prev->tok == "&") { v->addrTaken = true; v->read = true; continue; }
        if (nx && nx->tok == "[") {
            v->read = true;
            // array index check
            if (v->isArray && v->arraySize >= 0) {
                long long idx;
                Token* close = nx->link;
                if (close && evalConstExpr(nx->next, close, tu, idx)) {
                    if (idx < 0) {
                        Location loc(file, nx->line, nx->col);
                        report2(rep, "negativeIndex", "error", "Negative array index", 786, loc);
                    } else if (idx >= v->arraySize) {
                        Location loc(file, nx->line, nx->col);
                        std::ostringstream os;
                        os << "Array '" << v->name << "[" << v->arraySize << "]' accessed at index "
                           << idx << ", which is out of bounds.";
                        report2(rep, "arrayIndexOutOfBounds", "error", os.str(), 788, loc);
                    }
                }
            }
            continue;
        }
        if (nx && (nx->tok == "." || nx->tok == "->")) {
            v->read = true;
            if (nx->next && nx->next->isName) usedMembers.insert(nx->next->tok);
            continue;
        }
        v->read = true;
    }

    // ---- reports
    if (!settings.severityEnabled("unusedVariable")) {
        // style checks need the style severity
    }
    const bool style = settings.severityEnabled("style");
    const bool err = settings.severityEnabled("error") || true;
    for (Var2& v : tu.vars) {
        if (v.isParam || v.isGlobal) continue;
        if (!v.used && !v.assigned && !v.read) {
            if (style) report2(rep, "unusedVariable", "style", "Unused variable: " + v.name, 563,
                               Location(file, v.declLine, v.declCol));
            continue;
        }
        if (!v.assigned && v.read) {
            if (err) report2(rep, "uninitvar", "error", "Uninitialized variable: " + v.name, 907,
                             Location(file, v.firstReadLine, v.firstReadCol));
            if (style) report2(rep, "unassignedVariable", "style", "Variable '" + v.name + "' is not assigned a value.", 665,
                               Location(file, v.declLine, v.declCol));
            continue;
        }
        if (v.assigned && !v.read) {
            if (style) report2(rep, "unreadVariable", "style",
                               "Variable '" + v.name + "' is assigned a value that is never used.", 563,
                               Location(file, v.assignTok ? v.assignTok->line : v.declLine,
                                        v.assignTok ? v.assignTok->col : v.declCol));
            continue;
        }
    }
    // ---- unused struct members
    if (style) {
        for (Struct2& s : tu.structs) {
            bool usedStruct = false;
            for (Token* t = first; t; t = t->next) if (t->isName && t->tok == s.name) { usedStruct = true; break; }
            if (!usedStruct) continue;
            for (auto& m : s.members) {
                if (usedMembers.count(m.first)) continue;
                report2(rep, "unusedStructMember", "style",
                        "struct member '" + s.name + "::" + m.first + "' is never used.", 563, m.second);
            }
        }
    }
    // ---- functions
    for (Func2& f : tu.funcs) {
        if (!f.isDefinition) continue;
        functionNames.insert(f.name);
    }
    for (Var2& v : tu.vars) { (void)v; }
}
