void Analysis::checkWholeProgram(const std::map<std::string, Location>& functionNames,
                                 const std::set<std::string>& calledFunctions)
{
    if (!settings->severityEnabled("unusedFunction")) return;
    Reporter* rep = (Reporter*)reporter;
    for (const auto& kv : functionNames) {
        if (kv.first == "main") continue;
        if (calledFunctions.count(kv.first)) continue;
        ErrorMessage e;
        e.id = "unusedFunction";
        e.severity = "style";
        e.msg = "The function '" + kv.first + "' is never used.";
        e.verbose = e.msg;
        e.cwe = 561;
        e.locations.push_back(kv.second);
        e.symbols.push_back(kv.first);
        rep->error(e);
    }
}

