{"command": "cd /workspace && python3 - <<'PYEOF'
s=open('src/analyze.cpp').read()
s=s.replace('    fprintf(stderr,"A\\n");\n','')
s=s.replace('    fprintf(stderr,"B\\n");\n','')
s=s.replace('    fprintf(stderr,"C\\n");\n','')
s=s.replace('    fprintf(stderr,"D\\n");\n','')
s=s.replace('    fprintf(stderr,"E\\n");\n','')
s=s.replace('    fprintf(stderr,"F\\n");\n','')
s=s.replace('    fprintf(stderr,"G\\n");\n','')
# 1. function definition name tokens must not be treated as calls
s=s.replace('''    // tokens inside function bodies
    std::set<Token*> inFunc;''','''    std::set<Token*> funcNameTokens;
    for (const Func2& f : tu.funcs) {
        if (!f.body) continue;
        Token* nm = f.body->prev;   // ')'
        Token* op = nm ? nm->link : nullptr;
        if (op && op->prev) funcNameTokens.insert(op->prev);
    }
    // tokens inside function bodies
    std::set<Token*> inFunc;''')
s=s.replace('''    for (Token* t = first; t; t = t->next) {
        if (!t->isName) continue;
        auto dn = tu.declNameTokens.find(t);''','''    for (Token* t = first; t; t = t->next) {
        if (!t->isName) continue;
        if (funcNameTokens.count(t)) continue;
        auto dn = tu.declNameTokens.find(t);''')
# 2. array element writes mark the array as assigned
s=s.replace('''        if (nx && nx->tok == "[") {
            if (!v->read) { v->firstReadLine = t->line; v->firstReadCol = t->col; }
            v->read = true;''','''        if (nx && nx->tok == "[") {
            if (!v->read) { v->firstReadLine = t->line; v->firstReadCol = t->col; }
            v->read = true;
            {
                Token* close = nx->link;
                Token* after = close ? close->next : nullptr;
                if (after && (after->tok == "=" || after->tok == "+=" || after->tok == "-=" ||
                              after->tok == "*=" || after->tok == "/=" || after->tok == "%=" ||
                              after->tok == "&=" || after->tok == "|=" || after->tok == "^=")) {
                    v->assigned = true;
                    if (after->tok == "=" && !v->assignTok) v->assignTok = after;
                    continue;
                }
            }''')
# 3. arrays: no uninitvar/unassignedVariable
s=s.replace('''        if (!v.assigned && v.read) {
            if (err) report2(rep, "uninitvar"''','''        if (!v.assigned && v.read && !v.isArray) {
            if (err) report2(rep, "uninitvar"''')
s=s.replace('''        if (!v.used && !v.assigned && !v.read) {
            if (style) report2(rep, "unusedVariable"''','''        if (!v.used && !v.assigned && !v.read && !v.isArray) {
            if (style) report2(rep, "unusedVariable"''')
open('src/analyze.cpp','w').write(s)
PYEOF
grep -c fprintf src/analyze.cpp; ./compile.sh 2>&1|head -3; cd /tmp/mytest && for f in a.c b.c c.c d.c err.c; do echo "=== $f"; timeout 10 /workspace/executable --enable=all $f 2>&1; done"}

