new='''static std::string labelForCondition(const std::string& cond, const std::string& dir)
{
    std::string c = cond;
    std::size_t b = 0, e = c.size();
    while (b < e && std::isspace((unsigned char)c[b])) ++b;
    while (e > b && std::isspace((unsigned char)c[e-1])) --e;
    c = c.substr(b, e - b);
    if (dir == "ifdef") return c + "=" + c;
    if (dir == "ifndef") return std::string();
    // scan the condition for defined()/!defined() and simple comparisons
    std::vector<std::string> toks = tokenizeExpr(c);
    std::string out;
    for (std::size_t i = 0; i < toks.size(); ++i) {
        bool neg = false;
        std::size_t k = i;
        if (toks[k] == "!") { neg = true; ++k; }
        if (k < toks.size() && toks[k] == "defined") {
            ++k;
            std::string name;
            if (k < toks.size() && toks[k] == "(") {
                ++k;
                if (k < toks.size()) { name = toks[k]; ++k; }
                if (k < toks.size() && toks[k] == ")") ++k;
            } else if (k < toks.size()) { name = toks[k]; ++k; }
            if (!name.empty()) {
                if (!out.empty()) out += ";";
                out += neg ? name : (name + "=" + name);
            }
            i = k - 1;
            continue;
        }
        if (!neg && k < toks.size() && toks[k] == "(" ) continue;
    }
    if (!out.empty()) return out;
    // X == N  (or N == X)
    {
        std::size_t p = c.find("==");
        if (p != std::string::npos) {
            std::string lhs = c.substr(0, p), rhs = c.substr(p + 2);
            auto trim = [](std::string t) {
                std::size_t b2 = 0, e2 = t.size();
                while (b2 < e2 && std::isspace((unsigned char)t[b2])) ++b2;
                while (e2 > b2 && std::isspace((unsigned char)t[e2-1])) --e2;
                return t.substr(b2, e2 - b2);
            };
            lhs = trim(lhs); rhs = trim(rhs);
            if (!lhs.empty() && isIdentStart(lhs[0])) return lhs + "=" + rhs;
            if (!rhs.empty() && isIdentStart(rhs[0])) return rhs + "=" + lhs;
            return std::string();
        }
    }
    // plain macro name
    if (!c.empty() && isIdentStart(c[0])) {
        bool allIdent = true;
        for (char ch : c) if (!isIdentChar(ch)) allIdent = false;
        if (allIdent) return c;
    }
    return std::string();
}

