// configuration is always included as well.
struct CondInfo {
    std::string dir;
    std::string cond;
    std::set<std::string> posDefined;
};

static void collectCondInfo(const std::vector<SourceLine>& logical, std::vector<CondInfo>& out)
{
    for (const SourceLine& sl : logical) {
        const std::string& text = sl.text;
        std::size_t p = 0;
        while (p < text.size() && (text[p]==' '||text[p]=='\\t')) ++p;
        if (p >= text.size() || text[p] != '#') continue;
        std::size_t q = p + 1;
        while (q < text.size() && std::isspace((unsigned char)text[q])) ++q;
        std::size_t e = q;
        while (e < text.size() && isIdentChar(text[e])) ++e;
        std::string dir = text.substr(q, e - q);
        if (dir != "if" && dir != "ifdef" && dir != "ifndef" && dir != "elif") continue;
        std::string rest = text.substr(e);
        std::string cond;
        if (dir == "ifdef" || dir == "ifndef") {
            std::size_t r = 0;
            while (r < rest.size() && std::isspace((unsigned char)rest[r])) ++r;
            std::size_t s = r;
            while (s < rest.size() && isIdentChar(rest[s])) ++s;
            cond = rest.substr(r, s - r);
        } else cond = rest;
        CondInfo ci;
        ci.dir = dir;
        ci.cond = cond;
        if (dir == "ifdef") {
            if (!cond.empty()) ci.posDefined.insert(cond);
        } else if (dir == "ifndef") {
            // nothing has to be defined
        } else {
            std::vector<std::string> toks = tokenizeExpr(cond);
            for (std::size_t i = 0; i < toks.size(); ++i) {
                bool neg = false;
                std::size_t k = i;
                if (toks[k] == "!") { neg = true; ++k; }
                if (k < toks.size() && toks[k] == "defined") {
                    ++k;
                    std::string name;
                    if (k < toks.size() && toks[k] == "(") {
                        ++k;
                        if (k < toks.size()) { name = toks[k]; ++k; }
                        if (k < toks.size() && toks[k] == ")") ++k;
                    } else if (k < toks.size()) { name = toks[k]; ++k; }
                    if (!name.empty() && !neg) ci.posDefined.insert(name);
                    i = k - 1;
                    continue;
                }
                if (!neg && k < toks.size() && toks[k].size() > 0 && isIdentStart(toks[k][0]) &&
                    toks[k] != "defined") {
                    bool allIdent = true;
                    for (char ch : toks[k]) if (!isIdentChar(ch)) allIdent = false;
                    if (allIdent) ci.posDefined.insert(toks[k]);
                }
            }
            // X == N
            std::size_t pe = cond.find("==");
            if (pe != std::string::npos) {
                std::string lhs = cond.substr(0, pe), rhs = cond.substr(pe + 2);
                auto trim = [](std::string t) {
                    std::size_t b2 = 0, e2 = t.size();
                    while (b2 < e2 && std::isspace((unsigned char)t[b2])) ++b2;
                    while (e2 > b2 && std::isspace((unsigned char)t[e2-1])) --e2;
                    return t.substr(b2, e2 - b2);
                };
                lhs = trim(lhs); rhs = trim(rhs);
                if (!lhs.empty() && isIdentStart(lhs[0])) ci.posDefined.insert(lhs);
                else if (!rhs.empty() && isIdentStart(rhs[0])) ci.posDefined.insert(rhs);
            }
        }
        out.push_back(ci);
    }
}

static std::vector<std::set<std::string> > configCombinations(const std::vector<SourceLine>& logical,
                                                              const std::map<std::string, std::string>& cliDefines)
{
    std::vector<CondInfo> conds;
    collectCondInfo(logical, conds);
    std::vector<std::set<std::string> > out;
    out.push_back(std::set<std::string>());
    for (const CondInfo& ci : conds) {
        if (ci.posDefined.empty()) continue;
        bool found = false;
        for (const std::set<std::string>& c : out) if (c == ci.posDefined) { found = true; break; }
        if (!found) out.push_back(ci.posDefined);
    }
    (void)cliDefines;
    return out;
}

