actions.command:
cd /workspace && python3 - <<'PYEOF'
s=open('src/analyze.cpp').read()
i=s.index('static void analyseTU(const std::string& file,')
j=s.index('// ---------------------------------------------------------------------------\n// Analysis entry points')
new = '''static void analyseTU(const std::string& file, const std::vector<SourceLine>& lines,
                      Reporter& rep, const Settings& settings,
                      std::map<std::string, Location>& functionNames, std::set<std::string>& calledFunctions,
                      bool& criticalError)
{
    Token* first = tokenizeCode(lines);
    if (!first) return;
    TU tu;

    // ---- struct / class / union definitions
    std::vector<std::pair<Token*,Token*> > structBodies;
    for (Token* t = first; t; t = t->next) {
        if (t->tok != "struct" && t->tok != "class" && t->tok != "union") continue;
        Token* n = t->next;
        if (!n || !n->isName || n->tok == "{") continue;
        Token* brace = n->next;
        if (!brace || brace->tok != "{") continue;
        Struct2 s;
        s.name = n->tok;
        tu.typeNames.insert(n->tok);
        for (Token* m = brace->next; m && m != brace->link; m = m->next) {
            DeclResult d = parseDecl(m, tu.typeNames, 6);
            if (d.nameTok) {
                s.members.push_back({d.nameTok->tok, Location(file, d.nameTok->line, d.nameTok->col)});
                while (m && m->tok != ";" && m != brace->link) m = m->next;
                if (!m) break;
            }
        }
        tu.structs.push_back(s);
        structBodies.push_back({brace, brace->link});
    }
    for (Token* t = first; t; t = t->next) {
        if (t->tok == "typedef") {
            for (Token* q = t->next; q && q->tok != ";"; q = q->next) if (q->isName) tu.typeNames.insert(q->tok);
        }
    }
    std::set<Token*> inStruct;
    for (const auto& b : structBodies)
        for (Token* t = b.first->next; t && t != b.second; t = t->next) inStruct.insert(t);

    // ---- function definitions
    for (Token* t = first; t; t = t->next) {
        if (!t->isName || isKeywordTok(t->tok)) continue;
        if (t->prev && (t->prev->tok == "." || t->prev->tok == "->" || t->prev->tok == "::")) continue;
        if (inStruct.count(t)) continue;
        if (t->next && t->next->tok == "(" && t->next->link) {
            Token* close = t->next->link;
            Token* after = close->next;
            if (after && after->tok == "{") {
                Func2 f;
                f.name = t->tok;
                f.line = t->line;
                f.col = t->col;
                f.body = after;
                f.isDefinition = true;
                Token* p = t->prev;
                bool voidRet = false;
                while (p && (isTypeQualifier(p->tok) || p->tok == "*" || p->tok == "&")) {
                    if (p->tok == "void") voidRet = true;
                    p = p->prev;
                }
                if (p && p->tok == "void") voidRet = true;
                f.returnsVoid = voidRet;
                tu.funcs.push_back(f);
            }
        }
    }
    std::set<Token*> funcNameTokens;
    std::map<Token*, std::size_t> bodyOwner;    // token inside a body -> function index
    for (std::size_t fi = 0; fi < tu.funcs.size(); ++fi) {
        const Func2& f = tu.funcs[fi];
        if (!f.body) continue;
        Token* nm = f.body->prev;   // ')'
        Token* op = nm ? nm->link : nullptr;
        if (op && op->prev) funcNameTokens.insert(op->prev);
        for (Token* t = f.body->next; t && t != f.body->link; t = t->next) bodyOwner[t] = fi;
    }

    // ---- parameter declarations
    for (std::size_t fi = 0; fi < tu.funcs.size(); ++fi) {
        const Func2& f = tu.funcs[fi];
        if (!f.body) continue;
        Token* open = f.body->prev ? f.body->prev->link : nullptr;
        Token* close = f.body->prev;
        if (!open || !close) continue;
        for (Token* t = open->next; t && t != close; t = t->next) {
            if (!t->isName || isKeywordTok(t->tok) || isTypeQualifier(t->tok)) continue;
            DeclResult d = parseDecl(t, tu.typeNames, 6);
            if (!d.nameTok) continue;
            Var2 v;
            v.name = d.nameTok->tok;
            v.type = d.type;
            v.isArray = d.isArray;
            v.arraySize = d.arraySize;
            v.isPointer = d.isPointer;
            v.isStruct = d.isStruct;
            v.isConst = d.isConst;
            v.declLine = d.nameTok->line;
            v.declCol = d.nameTok->col;
            v.declTok = d.nameTok;
            v.isParam = true;
            v.inFunction = true;
            tu.vars.push_back(v);
            tu.declNameTokens[d.nameTok] = &tu.vars.back();
            while (t && t->tok != "," && t != close) t = t->next;
            if (!t || t == close) break;
        }
    }

    // ---- global declarations
    {
        std::map<std::string, Var2*> current;
        for (Token* t = first; t; t = t->next) {
            if (bodyOwner.count(t)) continue;
            if (inStruct.count(t)) continue;
            if (!t->isName) continue;
            if (isKeywordTok(t->tok) || isTypeQualifier(t->tok)) continue;
            if (funcNameTokens.count(t)) continue;
            DeclResult d = parseDecl(t, tu.typeNames, 8);
            if (!d.nameTok) continue;
            Var2 v;
            v.name = d.nameTok->tok;
            v.type = d.type;
            v.isArray = d.isArray;
            v.arraySize = d.arraySize;
            v.isPointer = d.isPointer;
            v.isStruct = d.isStruct;
            v.isConst = d.isConst;
            v.declLine = d.nameTok->line;
            v.declCol = d.nameTok->col;
            v.declTok = d.nameTok;
            v.isGlobal = true;
            tu.vars.push_back(v);
            tu.declNameTokens[d.nameTok] = &tu.vars.back();
            current[d.nameTok->tok] = &tu.vars.back();
            Token* q = d.nameTok;
            while (q && q->tok != ";" && q->tok != "{" && q->tok != "}" && q->tok != ")") q = q->next;
            if (q && q != d.nameTok) t = q->prev;
        }
    }

    struct ArrayWrite { Var2* v; std::string index; Token* eq; };
    std::vector<ArrayWrite> arrayWrites;
    std::set<std::string> usedMembers;

    // helper lambda: process the tokens of one scope
    auto processScope = [&](Token* start, Token* end, bool inFunction) {
        std::map<std::string, Var2*> current;
        // pre-fill with the parameters of this function
        if (inFunction) {
            for (Var2& v : tu.vars) if (v.isParam) current[v.name] = &v;
        }
        int depth = 0;
        for (Token* t = start; t && t != end; t = t->next) {
            if (t->tok == "{") { ++depth; continue; }
            if (t->tok == "}") { --depth; continue; }
            if (!t->isName) continue;
            if (isKeywordTok(t->tok) || isTypeQualifier(t->tok)) continue;
            if (funcNameTokens.count(t)) continue;
            if (tu.declNameTokens.find(t) == tu.declNameTokens.end()) {
                // possible declaration
                DeclResult d = parseDecl(t, tu.typeNames, 8);
                if (d.nameTok) {
                    Var2 v;
                    v.name = d.nameTok->tok;
                    v.type = d.type;
                    v.isArray = d.isArray;
                    v.arraySize = d.arraySize;
                    v.isPointer = d.isPointer;
                    v.isStruct = d.isStruct;
                    v.isConst = d.isConst;
                    v.declLine = d.nameTok->line;
                    v.declCol = d.nameTok->col;
                    v.declTok = d.nameTok;
                    v.inFunction = inFunction;
                    v.isGlobal = !inFunction;
                    tu.vars.push_back(v);
                    Var2* pv = &tu.vars.back();
                    tu.declNameTokens[d.nameTok] = pv;
                    current[d.nameTok->tok] = pv;
                    Token* q = d.nameTok;
                    while (q && q != end && q->tok != ";" && q->tok != "{" && q->tok != "}" && q->tok != ")") q = q->next;
                    if (q && q != d.nameTok && q->prev) t = q->prev;
                    continue;
                }
            }
            auto it = current.find(t->tok);
            if (it == current.end()) {
                if (t->next && t->next->tok == "(") calledFunctions.insert(t->tok);
                continue;
            }
            Var2* v = it->second;
            if (tu.declNameTokens.find(t) != tu.declNameTokens.end() && tu.declNameTokens[t] == v) {
                Token* nx = t->next;
                if (nx && nx->tok == "=") {
                    v->assigned = true;
                    v->assignTok = nx;
                    long long val;
                    if (nx->next && nx->next->isNum && isIntegerLiteral(nx->next->tok, val) &&
                        tu.constCount.find(v->name) == tu.constCount.end()) {
                        tu.constVal[v->name] = (int)val;
                        tu.constCount[v->name] = 1;
                    }
                }
                continue;
            }
            v->used = true;
            Token* nx = t->next;
            if (nx && (nx->tok == "=" || nx->tok == "+=" || nx->tok == "-=" || nx->tok == "*=" ||
                       nx->tok == "/=" || nx->tok == "%=" || nx->tok == "&=" || nx->tok == "|=" ||
                       nx->tok == "^=" || nx->tok == "<<=" || nx->tok == ">>=")) {
                if (nx->tok == "=") {
                    if (!v->assigned) {
                        v->assigned = true;
                        v->assignTok = nx;
                        long long val;
                        if (nx->next && nx->next->isNum && isIntegerLiteral(nx->next->tok, val) &&
                            tu.constCount.find(v->name) == tu.constCount.end()) {
                            tu.constVal[v->name] = (int)val;
                            tu.constCount[v->name] = 1;
                        }
                    }
                } else { v->assigned = true; v->read = true; }
                continue;
            }
            if (nx && (nx->tok == "++" || nx->tok == "--")) { v->assigned = true; v->read = true; continue; }
            if (t->prev && (t->prev->tok == "++" || t->prev->tok == "--")) { v->assigned = true; v->read = true; continue; }
            if (t->prev && t->prev->tok == "&") { v->addrTaken = true; v->read = true; continue; }
            if (nx && nx->tok == "[") {
                Token* close = nx->link;
                Token* after = close ? close->next : nullptr;
                const bool isWrite = after && (after->tok == "=" || after->tok == "+=" || after->tok == "-=" ||
                                               after->tok == "*=" || after->tok == "/=" || after->tok == "%=" ||
                                               after->tok == "&=" || after->tok == "|=" || after->tok == "^=");
                if (isWrite) {
                    v->assigned = true;
                    if (after->tok == "=" && !v->assignTok) v->assignTok = after;
                } else {
                    if (!v->read) { v->firstReadLine = t->line; v->firstReadCol = t->col; }
                    v->read = true;
                }
                if (v->isArray && v->arraySize >= 0) {
                    long long idx;
                    if (close && evalConstExpr(nx->next, close, tu, idx)) {
                        if (idx < 0) {
                            report2(rep, "negativeIndex", "error", "Negative array index", 786,
                                    Location(file, nx->line, nx->col));
                        } else if (idx >= v->arraySize) {
                            std::ostringstream os;
                            os << "Array '" << v->name << "[" << v->arraySize << "]' accessed at index "
                               << idx << ", which is out of bounds.";
                            report2(rep, "arrayIndexOutOfBounds", "error", os.str(), 788,
                                    Location(file, nx->line, nx->col));
                        }
                    }
                }
                if (isWrite && after && after->tok == "=") {
                    std::string idxText;
                    for (Token* q = nx->next; close && q && q != close; q = q->next) idxText += q->tok;
                    arrayWrites.push_back({v, idxText, after});
                }
                continue;
            }
            if (nx && (nx->tok == "." || nx->tok == "->")) {
                Token* member = nx->next;
                Token* mAfter = member ? member->next : nullptr;
                const bool memberWrite = mAfter && (mAfter->tok == "=" || mAfter->tok == "+=" || mAfter->tok == "-=" ||
                                                    mAfter->tok == "*=" || mAfter->tok == "/=" || mAfter->tok == "%=" ||
                                                    mAfter->tok == "&=" || mAfter->tok == "|=" || mAfter->tok == "^=" ||
                                                    mAfter->tok == "++" || mAfter->tok == "--");
                if (memberWrite) v->assigned = true;
                else {
                    if (!v->read) { v->firstReadLine = t->line; v->firstReadCol = t->col; }
                    v->read = true;
                }
                if (member && member->isName) usedMembers.insert(member->tok);
                continue;
            }
            if (!v->read) { v->firstReadLine = t->line; v->firstReadCol = t->col; }
            v->read = true;
        }
    };

    // per function scopes
    for (std::size_t fi = 0; fi < tu.funcs.size(); ++fi) {
        const Func2& f = tu.funcs[fi];
        if (!f.body) continue;
        processScope(f.body->next, f.body->link, true);
    }
    // global scope
    processScope(first, nullptr, false);

    // ---- reports
    const bool style = settings.severityEnabled("style");
    for (Var2& v : tu.vars) {
        if (v.isParam || v.isGlobal) continue;
        if (!v.used && !v.assigned && !v.read && !v.isArray) {
            if (style) report2(rep, "unusedVariable", "style", "Unused variable: " + v.name, 563,
                               Location(file, v.declLine, v.declCol));
            continue;
        }
        if (!v.assigned && v.read && !v.isArray) {
            report2(rep, "uninitvar", "error", "Uninitialized variable: " + v.name, 907,
                    Location(file, v.firstReadLine, v.firstReadCol));
            if (style) report2(rep, "unassignedVariable", "style", "Variable '" + v.name + "' is not assigned a value.", 665,
                               Location(file, v.declLine, v.declCol));
            continue;
        }
        if (v.isArray && v.assigned && !v.read) {
            if (style) {
                for (const auto& aw : arrayWrites) {
                    if (aw.v != &v) continue;
                    report2(rep, "unreadVariable", "style",
                            "Variable '" + v.name + "[" + aw.index + "]' is assigned a value that is never used.", 563,
                            Location(file, aw.eq->line, aw.eq->col));
                }
            }
            continue;
        }
        if (v.assigned && !v.read && !v.isStruct) {
            if (style) report2(rep, "unreadVariable", "style",
                               "Variable '" + v.name + "' is assigned a value that is never used.", 563,
                               Location(file, v.assignTok ? v.assignTok->line : v.declLine,
                                        v.assignTok ? v.assignTok->col : v.declCol));
            continue;
        }
    }
    if (style) {
        for (Struct2& s : tu.structs) {
            bool usedStruct = false;
            for (Token* t = first; t; t = t->next) if (t->isName && t->tok == s.name) { usedStruct = true; break; }
            if (!usedStruct) continue;
            for (auto& m : s.members) {
                if (usedMembers.count(m.first)) continue;
                report2(rep, "unusedStructMember", "style",
                        "struct member '" + s.name + "::" + m.first + "' is never used.", 563, m.second);
            }
        }
    }
    for (const Func2& f : tu.funcs) {
        if (!f.isDefinition) continue;
        if (functionNames.find(f.name) == functionNames.end())
            functionNames[f.name] = Location(file, f.line, f.col);
    }
}

