            std::vector<std::string> toks;
            const std::string& text = sl.text;
            std::size_t i = 0;
            while (i < text.size()) {
                const char c = text[i];
                if (std::isspace((unsigned char)c)) { ++i; continue; }
                if (c == '"' || c == '\\'') {
                    std::size_t j = i + 1;
                    while (j < text.size()) { if (text[j]=='\\\\') { j += 2; continue; } if (text[j]==c) { ++j; break; } ++j; }
                    toks.push_back(text.substr(i, j - i));
