                if (isDigitCh(c)) {
                    std::size_t j = i;
                    while (j < text.size() && (isIdentChar(text[j]) || text[j]=='.')) ++j;
                    toks.push_back(text.substr(i, j - i));
                    i = j;
                    continue;
                }
                static const char* ops2[] = {"&&","||","==","!=","<=",">=","<<",">>","+=","-=","*=","/=","%=","&=","|=","^=","->","::","++","--",nullptr};
                std::string op;
                for (int k = 0; ops2[k]; ++k) if (text.compare(i, 2, ops2[k]) == 0) { op = ops2[k]; break; }
                std::size_t len = op.empty() ? 1 : op.size();
                toks.push_back(text.substr(i, len));
                i += len;
            }
            for (std::size_t k = 0; k < toks.size(); ++k) {
                if (k) out << " ";
                out << toks[k];
            }
