actions.command:
cd /workspace && python3 - <<'PYEOF'
s=open('src/analyze.cpp').read()
old='''                DeclResult d = parseDecl(t, tu.typeNames, 8);
                if (d.nameTok) {
                    Var2 v;
                    v.name = d.nameTok->tok;
                    v.type = d.type;
                    v.isArray = d.isArray;
                    v.arraySize = d.arraySize;
                    v.isPointer = d.isPointer;
                    v.isStruct = d.isStruct;
                    v.isReference = d.isReference;
                    v.isConst = d.isConst;
                    v.declLine = d.nameTok->line;
                    v.declCol = d.nameTok->col;
                    v.declTok = d.nameTok;
                    v.inFunction = inFunction;
                    v.isGlobal = !inFunction;
                    tu.vars.push_back(v);
                    Var2* pv = &tu.vars.back();
                    tu.declNameTokens[d.nameTok] = pv;
                    current[d.nameTok->tok] = pv;
                    {
                        Token* nx2 = d.nameTok->next;
                        if (nx2 && nx2->tok == "=") {
                            pv->assigned = true;
                            pv->assignTok = nx2;
                            long long val;
                            if (nx2->next && nx2->next->isNum && isIntegerLiteral(nx2->next->tok, val) &&
                                tu.constCount.find(pv->name) == tu.constCount.end()) {
                                tu.constVal[pv->name] = (int)val;
                                tu.constCount[pv->name] = 1;
                            }
                        }
                    }
                    Token* q = d.nameTok;
                    while (q && q != end && q->tok != ";" && q->tok != "{" && q->tok != "}" && q->tok != ")") q = q->next;
                    if (q && q != d.nameTok && q->prev) t = q->prev;
                    continue;
                }'''
new='''                DeclResult d = parseDecl(t, tu.typeNames, 8);
                if (d.nameTok) {
                    Token* last = d.nameTok;
                    Token* pos = d.nameTok;
                    bool first = true;
                    while (true) {
                        DeclResult dd = first ? d : DeclResult();
                        if (!first) {
                            // additional declarators of the same declaration
                            dd.type = d.type;
                            dd.isStruct = d.isStruct;
                            while (pos && (pos->tok == "*" || pos->tok == "&")) pos = pos->next;
                            if (!pos || !pos->isName || isKeywordTok(pos->tok) || isTypeQualifier(pos->tok)) break;
                            dd.nameTok = pos;
                            Token* after2 = pos->next;
                            if (!after2) break;
                            if (!(after2->tok == ";" || after2->tok == "=" || after2->tok == "," ||
                                  after2->tok == "[" || after2->tok == ")")) break;
                            if (after2->tok == "[") {
                                dd.isArray = true;
                                Token* cl = after2->link;
                                if (cl && cl->next && cl->next->isNum) isIntegerLiteral(cl->next->tok, dd.arraySize);
                            }
                        }
                        first = false;
                        Var2 v;
                        v.name = dd.nameTok->tok;
                        v.type = dd.type;
                        v.isArray = dd.isArray;
                        v.arraySize = dd.arraySize;
                        v.isPointer = dd.isPointer;
                        v.isStruct = dd.isStruct;
                        v.isReference = dd.isReference;
                        v.isConst = dd.isConst;
                        v.declLine = dd.nameTok->line;
                        v.declCol = dd.nameTok->col;
                        v.declTok = dd.nameTok;
                        v.inFunction = inFunction;
                        v.isGlobal = !inFunction;
                        tu.vars.push_back(v);
                        Var2* pv = &tu.vars.back();
                        tu.declNameTokens[dd.nameTok] = pv;
                        current[dd.nameTok->tok] = pv;
                        {
                            Token* nx2 = dd.nameTok->next;
                            if (nx2 && nx2->tok == "=") {
                                pv->assigned = true;
                                pv->assignTok = nx2;
                                long long val;
                                if (nx2->next && nx2->next->isNum && isIntegerLiteral(nx2->next->tok, val) &&
                                    tu.constCount.find(pv->name) == tu.constCount.end()) {
                                    tu.constVal[pv->name] = (int)val;
                                    tu.constCount[pv->name] = 1;
                                }
                            }
                        }
                        last = dd.nameTok;
                        pos = dd.nameTok->next;
                        if (!pos || pos->tok != ",") break;
                        pos = pos->next;
                        if (pos && pos->tok == "[") { pos = pos->link ? pos->link->next : pos->next; if (pos && pos->tok != ",") break; }
                    }
                    t = last;
                    continue;
                }'''
assert old in s
s=s.replace(old,new)
open('src/analyze.cpp','w').write(s)
