function.arguments:
{"command": "cd /workspace && python3 - <<'PYEOF'
s=open('src/analyze.cpp').read()
old='''                    Token* q = d.nameTok;
                    while (q && q != end && q->tok != ";" && q->tok != "{" && q->tok != "}" && q->tok != ")") q = q->next;
                    if (q && q != d.nameTok && q->prev) t = q->prev;
                    continue;
                }'''
new='''                    // further declarators of the same declaration
                    Token* last = d.nameTok;
                    Token* pos = d.nameTok->next;
                    while (pos && pos->tok == ",") {
                        pos = pos->next;
                        while (pos && (pos->tok == "*" || pos->tok == "&")) pos = pos->next;
                        if (!pos || !pos->isName || isKeywordTok(pos->tok) || isTypeQualifier(pos->tok)) break;
                        Token* after2 = pos->next;
                        if (!after2) break;
                        if (!(after2->tok == ";" || after2->tok == "=" || after2->tok == "," || after2->tok == "[")) break;
                        Var2 v2;
                        v2.name = pos->tok;
                        v2.type = d.type;
                        v2.isPointer = d.isPointer;
                        v2.isStruct = d.isStruct;
                        v2.isConst = d.isConst;
                        if (after2->tok == "[") {
                            v2.isArray = true;
                            Token* cl = after2->link;
                            if (cl && cl->next && cl->next->isNum) isIntegerLiteral(cl->next->tok, v2.arraySize);
                        }
                        v2.declLine = pos->line;
                        v2.declCol = pos->col;
                        v2.declTok = pos;
                        v2.inFunction = inFunction;
                        v2.isGlobal = !inFunction;
                        tu.vars.push_back(v2);
                        Var2* pv2 = &tu.vars.back();
                        tu.declNameTokens[pos] = pv2;
                        current[pos->tok] = pv2;
                        if (after2->tok == "=") {
                            pv2->assigned = true;
                            pv2->assignTok = after2;
                            long long val;
                            if (after2->next && after2->next->isNum && isIntegerLiteral(after2->next->tok, val) &&
                                tu.constCount.find(pv2->name) == tu.constCount.end()) {
                                tu.constVal[pv2->name] = (int)val;
                                tu.constCount[pv2->name] = 1;
                            }
                        }
                        last = pos;
                        pos = after2;
                    }
                    t = last;
                    continue;
                }'''
assert old in s
s=s.replace(old,new)
open('src/analyze.cpp','w').write(s)
