class Reporter
{
public:
    explicit Reporter(const Settings& s) : settings(s)
    {
        if (!s.outputFileName.empty()) {
            file.open(s.outputFileName);
            if (!file.is_open())
                std::cerr << "cppcheck: error: failed to open the file: \"" << s.outputFileName << "\"." << std::endl;
