        } else stream = &std::cerr;
        if (!s.outputTemplate.empty()) templateText = s.outputTemplate;
        else if (s.templateName == "gcc") templateText = "{file}:{line}:{column}: warning: {message} [{id}]\n{code}";
        else if (s.templateName == "cppcheck1") templateText = "[{callstack}]: ({severity}) {message}";
        else if (s.templateName == "vs") templateText = "{file}({line}): {severity}: {message}";
        else if (s.templateName == "edit") templateText = "{file} +{line}: {severity}: {message}";
        else templateText = "{file}:{line}:{column}: {severity}: {message} [{id}]\n{code}";
        locationTemplate = s.outputTemplateLocation;
        if (!s.outputTemplateLocation.empty() && s.templateName.empty()) locationTemplate = s.outputTemplateLocation;
    }

    void begin()
    {
        if (!isXml()) return;
        std::ostream& os = *stream;
        os << "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n";
        os << "<results version=\"" << (settings.outputFormat == "xmlv3" ? "3" : "2") << "\">\n";
        os << "    <cppcheck version=\"2.19 dev\"/>\n";
        os << "    <errors>\n";
    }

    void plain(const std::string& msg) { *stream << msg << std::endl; }

    bool hasErrors() const { return errorCount > 0; }

    void error(const ErrorMessage& e)
    {
        if (e.severity == "error") ++errorCount;
        if (isXml()) { errors.push_back(e); return; }
        if (settings.outputFormat == "sarif") { errors.push_back(e); return; }
        *stream << report_detail::render(templateText, e, e.severity);
        *stream << std::endl;
        for (std::size_t i = 1; i < e.locations.size(); ++i) {
            if (locationTemplate.empty()) continue;
            ErrorMessage tmp;
            tmp.id = e.id;
            tmp.severity = e.severity;
            tmp.msg = e.locations[i].info;
            tmp.locations.push_back(e.locations[i]);
            *stream << report_detail::render(locationTemplate, tmp, e.severity);
            *stream << std::endl;
        }
    }

    void end(const std::vector<std::string>& activeCheckers)
    {
        if (settings.outputFormat == "xml" || settings.outputFormat == "xmlv2" || settings.outputFormat == "xmlv3") {
            std::ostream& os = *stream;
            for (const ErrorMessage& e : errors) {
                os << "        <error id=\"" << xmlEscape(e.id) << "\" severity=\"" << xmlEscape(e.severity)
                   << "\" msg=\"" << xmlEscape(e.msg) << "\" verbose=\"" << xmlEscape(e.verbose) << "\"";
                if (e.cwe) os << " cwe=\"" << e.cwe << "\"";
                if (e.inconclusive) os << " inconclusive=\"true\"";
                if (!e.file0().empty()) os << " file0=\"" << xmlEscape(e.file0()) << "\"";
                if (e.locations.empty() && e.symbols.empty()) { os << "/>\n"; continue; }
                os << ">\n";
                for (const Location& l : e.locations) {
                    os << "            <location file=\"" << xmlEscape(l.file) << "\" line=\"" << l.line << "\"";
                    if (l.column) os << " column=\"" << l.column << "\"";
                    if (!l.info.empty()) os << " info=\"" << xmlEscape(l.info) << "\"";
                    os << "/>\n";
                }
                for (const std::string& sym : e.symbols)
                    os << "            <symbol>" << xmlEscape(sym) << "</symbol>\n";
                os << "        </error>\n";
            }
            os << "    </errors>\n";
            if (settings.outputFormat == "xmlv3") {
                os << "\n    <critical-errors/>\n";
                os << "    <checkers-report>\n";
                for (const std::string& c : activeCheckers) os << "        <checker id=\"" << c << "\"/>\n";
                os << "    </checkers-report>\n";
            }
            os << "</results>\n";
            return;
        }
        if (settings.outputFormat == "sarif") writeSarif(activeCheckers);
    }

    bool isXml() const
    {
        return settings.outputFormat == "xml" || settings.outputFormat == "xmlv2" || settings.outputFormat == "xmlv3";
    }

    std::ostream* stream = &std::cerr;
    std::ofstream file;
    std::vector<ErrorMessage> errors;
    int errorCount = 0;

private:
