    {
        std::ostream& os = *stream;
        os << "{\n";
        os << "  \"version\": \"2.1.0\",\n";
        os << "  \"$schema\": \"https:\\/\\/docs.oasis-open.org\\/sarif\\/sarif\\/v2.1.0\\/errata01\\/os\\/schemas\\/sarif-schema-2.1.0.json\",\n";
        os << "  \"runs\": [\n";
