            os << "          \"locations\": [\n";
            for (std::size_t k = 0; k < e.locations.size(); ++k) {
                const Location& l = e.locations[k];
                os << "            {\n";
                os << "              \"physicalLocation\": {\n";
                os << "                \"artifactLocation\": {\n";
                os << "                  \"uri\": \"" << l.file << "\"\n";
                os << "                },\n";
                os << "                \"region\": {\n";
                os << "                  \"endColumn\": " << l.column << ",\n";
                os << "                  \"endLine\": " << l.line << ",\n";
                os << "                  \"startColumn\": " << l.column << ",\n";
                os << "                  \"startLine\": " << l.line << "\n";
                os << "                }\n";
                os << "              }\n";
                os << "            }" << (k + 1 < e.locations.size() ? "," : "") << "\n";
            }
            os << "          ],\n";
            os << "          \"message\": {\n";
            os << "            \"text\": \"" << e.msg << "\"\n";
            os << "          },\n";
            os << "          \"ruleId\": \"" << e.id << "\"\n";
            os << "        }" << (i + 1 < errors.size() ? "," : "") << "\n";
        }
        os << "      ],\n";
        os << "      \"tool\": {\n";
        os << "        \"driver\": {\n";
        os << "          \"informationUri\": \"https:\\/\\/cppcheck.sourceforge.io\",\n";
        os << "          \"name\": \"Cppcheck\",\n";
        os << "          \"rules\": [\n";
        // unique rules
        std::vector<const ErrorMessage*> rules;
        for (const ErrorMessage& e : errors) {
            bool found = false;
            for (const ErrorMessage* r : rules) if (r->id == e.id) { found = true; break; }
            if (!found) rules.push_back(&e);
        }
        for (std::size_t i = 0; i < rules.size(); ++i) {
            const ErrorMessage& e = *rules[i];
            os << "            {\n";
            os << "              \"defaultConfiguration\": {\n";
            os << "                \"level\": \"" << sarifLevel(e.severity) << "\"\n";
            os << "              },\n";
            os << "              \"fullDescription\": {\n";
            os << "                \"text\": \"\"\n";
            os << "              },\n";
            os << "              \"help\": {\n";
            os << "                \"text\": \"\"\n";
            os << "              },\n";
            os << "              \"id\": \"" << e.id << "\",\n";
            os << "              \"name\": \"\",\n";
            os << "              \"properties\": {\n";
            os << "                \"precision\": \"high\",\n";
            os << "                \"problem.severity\": \"" << e.severity << "\",\n";
            os << "                \"security-severity\": \"9.9\",\n";
            os << "                \"tags\": [\n";
            os << "                  \"external\\/cwe\\/cwe-" << (e.cwe ? e.cwe : 0) << "\",\n";
            os << "                  \"security\"\n";
            os << "                ]\n";
            os << "              },\n";
            os << "              \"shortDescription\": {\n";
            os << "                \"text\": \"\"\n";
            os << "              }\n";
            os << "            }" << (i + 1 < rules.size() ? "," : "") << "\n";
        }
        os << "          ],\n";
        os << "          \"semanticVersion\": \"2.19\"\n";
        os << "        }\n";
        os << "      }\n";
        os << "    }\n";
        os << "  ]\n";
        os << "}\n";
        (void)activeCheckers;
    }

    static const char* sarifLevel(const std::string& severity)
    {
        if (severity == "error") return "error";
        if (severity == "warning") return "warning";
        return "note";
    }

    const Settings& settings;
    std::string templateText;
    std::string locationTemplate;
};
